-- Priya's week 2 (days 8-14), hero 'priya': episodes, turns, phrases and her calendar.
-- The same week as Jun's (20-week2.sql, 21-trip.sql), seen from the product manager's side: she leads the client
-- relationship with Summit Retail. Same numbers as in Jun's week: $180,000 for phase one, Greg asks for one sixty-five,
-- five percent off with a one-year support contract, Net 45, 99.9 percent uptime, thirty days' notice.
-- Jun is in Ridgeport on days 11 and 12: he is only on the phone then.
-- An episode's turns are one statement, or two where six turns are too long for the DoltHub write API.
-- Try: node tools/seed-json.mjs db/seed/55-priya-week2.sql --out /tmp/claude-1000/priya2-try/db.js, then node tools/db-lint.mjs on it.
-- Push: node tools/dolt.mjs push db/seed/55-priya-week2.sql

REPLACE INTO episodes (id, title, title_ko, place, npc, day_from, day_to, time_from, time_to, requires, summary, summary_ko, reward, energy, sort, tags, hero) VALUES
  ('pr_d8_coffee', 'Coffee in the fog', '안개 낀 아침의 커피', 'coffee_cart', 'nina', 8, 8, '07:00', '10:30', NULL,
   'A foggy Monday morning at Nina''s cart. Get a large latte for yourself and a coffee for a coworker, and carry them both to the office.', '안개 낀 월요일 아침, 니나의 카트입니다. 당신이 마실 라테 큰 컵과 동료에게 줄 커피를 사서 사무실까지 들고 가세요.',
   -9, 9, 10, 'food,order,coffee,weather,small-talk', 'priya'),
  ('pr_d8_prep', 'Prepping the team for the kickoff', '킥오프 전에 팀과 준비하기', 'office_desk_team', 'derek', 8, 8, '08:30', '11:00', NULL,
   'An hour before the kickoff with Summit Retail, get the team ready: the game plan, who says what, and who does the talking on pricing.', '서밋 리테일과의 킥오프 한 시간 전, 팀을 준비시키세요. 진행 계획, 누가 무엇을 말할지, 가격 이야기는 누가 할지 정합니다.',
   0, 0, 20, 'meeting,planning,client,facilitation', 'priya'),
  ('pr_d8_kickoff', 'Running the kickoff call', '킥오프 콜 진행하기', 'office_meeting', 'greg', 8, 8, '10:30', '13:30', NULL,
   'Run the video call with Greg Whitfield and his team: introductions, the agenda, his goals for the dashboard, what you need from him, and a clear finish.', '그렉 휫필드와 그의 팀을 상대로 화상 통화를 진행하세요. 소개, 안건, 대시보드의 목표, 그에게 필요한 것, 그리고 깔끔한 마무리까지.',
   0, 0, 30, 'phone,client,meeting,facilitation,video-call', 'priya'),
  ('pr_d9_scope', 'The wish list: saying "not yet"', '위시리스트: "아직은 아니에요"라고 말하기', 'office_meeting', 'greg', 9, 9, '10:00', '13:30', 'pr_d8_kickoff',
   'Greg wants the dashboard, the mobile app and the wish list by November first. Protect the date without saying no: offer phases and a choice.', '그렉은 대시보드와 모바일 앱, 위시리스트까지 11월 1일에 원합니다. 안 된다고 말하지 않고 날짜를 지키세요. 단계를 나누고 선택지를 주는 겁니다.',
   0, 0, 10, 'phone,client,meeting,negotiation,video-call', 'priya');

REPLACE INTO episodes (id, title, title_ko, place, npc, day_from, day_to, time_from, time_to, requires, summary, summary_ko, reward, energy, sort, tags, hero) VALUES
  ('pr_d9_actions', 'Nailing down the action items', '액션 아이템 확실히 정하기', 'office_desk', 'jun', 9, 9, '13:00', '18:00', 'pr_d9_scope',
   'After the scope call, stop by Jun''s desk. Turn his notes into action items, each with an owner and a due date, before anything gets forgotten.', '범위 논의 통화가 끝난 뒤 준의 자리에 들르세요. 잊어버리기 전에 준의 메모를 담당자와 기한이 있는 액션 아이템으로 바꾸세요.',
   0, 0, 20, 'meeting,planning,follow-up', 'priya'),
  ('pr_d10_contract', 'Holding the line on the contract', '계약 조건에서 물러서지 않기', 'office_meeting', 'greg', 10, 10, '10:00', '13:30', 'pr_d9_scope',
   'Greg pushes on price, payment terms and uptime. Hold the line on the price, trade one thing for another, and do not agree to what you cannot approve.', '그렉이 가격, 지급 조건, 가동률을 밀어붙입니다. 가격은 지키고, 하나를 내주면 하나를 받고, 승인할 수 없는 것에는 동의하지 마세요.',
   0, 0, 10, 'phone,client,meeting,negotiation,contract,video-call', 'priya'),
  ('pr_d10_signoff', 'Getting Maya''s sign-off on the price', '마야에게 가격 승인 받기', 'office_manager', 'maya', 10, 10, '12:50', '18:00', 'pr_d10_contract',
   'Greg asked for one sixty-five. Give Maya the short version, make a recommendation, explain why, and agree on the ceiling.', '그렉이 16만 5천을 요구했습니다. 마야에게 요점만 보고하고, 의견을 제안하고, 이유를 설명하고, 양보의 상한선을 정하세요.',
   0, 0, 20, 'meeting,manager,negotiation,approval', 'priya'),
  ('pr_d10_refund', 'Did the gift card fix ship?', '기프트 카드 수정은 배포됐을까', 'office_desk_team', 'derek', 10, 10, '13:20', '18:30', NULL,
   'It is Wednesday, the day you promised Greg. Check with Derek that the gift card refund fix is live, ask about the one catch, and decide what to tell the client.', '그렉에게 약속한 수요일입니다. 데릭에게 기프트 카드 환불 수정이 배포됐는지 확인하고, 한 가지 걸리는 점을 묻고, 고객에게 무엇을 알릴지 정하세요.',
   0, 0, 30, 'office,release,follow-up,client', 'priya');

REPLACE INTO episodes (id, title, title_ko, place, npc, day_from, day_to, time_from, time_to, requires, summary, summary_ko, reward, energy, sort, tags, hero) VALUES
  ('pr_d11_clause', 'A last-minute clause', '막판에 끼어든 조항', 'office_meeting', 'greg', 11, 11, '09:00', '12:30', NULL,
   'Jun is on his way to Ridgeport when Greg calls: legal wants a penalty clause. Stay calm, buy time, find the real concern, and offer something better.', '준이 리지포트로 가고 있을 때 그렉이 전화합니다. 법무팀이 위약금 조항을 넣자고 합니다. 침착하게 시간을 벌고, 진짜 걱정을 알아내고, 더 나은 안을 내놓으세요.',
   0, 0, 10, 'phone,client,negotiation,contract,escalation', 'priya'),
  ('pr_d11_jun', 'Coaching Jun before the client visit', '고객 방문 전에 준에게 조언하기', 'office_desk_priya', 'jun', 11, 11, '12:00', '14:00', NULL,
   'Jun calls from his hotel in Ridgeport before his two o''clock meeting with Greg. Calm his nerves and tell him what to say and what not to promise.', '준이 그렉과의 두 시 회의를 앞두고 리지포트의 호텔에서 전화합니다. 긴장을 풀어 주고, 무엇을 말하고 무엇을 약속하지 말아야 하는지 알려 주세요.',
   0, 0, 20, 'phone,coaching,client,contract', 'priya'),
  ('pr_d12_signed', 'It''s official: the contract is signed', '공식 확정: 계약 체결', 'office_desk_priya', 'jun', 12, 12, '10:00', '14:00', NULL,
   'Jun calls from Ridgeport: the contract is signed. Congratulate him, ask how he handled the hard part, and make sure he takes the credit.', '준이 리지포트에서 전화합니다. 계약서에 서명이 끝났습니다. 축하하고, 어려운 대목을 어떻게 풀었는지 묻고, 준이 자기 공을 인정하게 해 주세요.',
   0, 0, 10, 'phone,praise,client,contract', 'priya'),
  ('pr_d12_headcount', 'Sharing the credit, asking for headcount', '공을 나누고 인력 요청하기', 'office_manager', 'maya', 12, 12, '12:50', '18:00', NULL,
   'Maya congratulates you on the contract. Share the credit with Jun and Derek, then make the case for one more developer on the team.', '마야가 계약 체결을 축하합니다. 준과 데릭에게 공을 돌린 뒤, 개발자가 한 명 더 필요한 이유를 설득력 있게 말하세요.',
   0, 0, 20, 'meeting,manager,praise,hiring,request', 'priya');

REPLACE INTO episodes (id, title, title_ko, place, npc, day_from, day_to, time_from, time_to, requires, summary, summary_ko, reward, energy, sort, tags, hero) VALUES
  ('pr_d12_hiring', 'Opening a position with Linda', '린다와 채용 공고 내기', 'office_hr', 'linda', 12, 12, '13:00', '18:00', 'pr_d12_headcount',
   'Maya approved one full-time developer. Go through the job requisition with Linda: the role, the hiring manager, the salary range and the timeline.', '마야가 정규직 개발자 한 명을 승인했습니다. 린다와 채용 요청서를 작성하세요. 직무, 채용 책임자, 연봉 범위, 일정까지.',
   0, 0, 30, 'hr,hiring,office', 'priya'),
  ('pr_w2_carl', 'Good news on a park bench', '공원 벤치에서 전하는 좋은 소식', 'park_bench', 'carl', 13, 13, '08:00', '18:00', NULL,
   'A warm, sunny Saturday in Seaside Park. Tell Carl about the deal, promise to unplug for the weekend, and say yes to his barbecue.', '따뜻하고 화창한 토요일, 시사이드 공원입니다. 칼에게 계약 소식을 전하고, 주말에는 일에서 손을 떼겠다고 약속하고, 바비큐 초대를 받아들이세요.',
   0, 0, 10, 'small-talk,park,invitation', 'priya'),
  ('pr_w2_rainy', 'A rainy Sunday at the diner', '비 오는 일요일의 다이너', 'diner_counter', 'rosa', 14, 14, '10:00', '20:00', NULL,
   'Showers all afternoon, and you forgot your umbrella. Sit at the counter, ask Rosa what is good on a day like this, wait out the rain, and pay in cash.', '오후 내내 소나기가 오는데 우산을 두고 나왔습니다. 카운터에 앉아 이런 날에 뭐가 좋은지 로사에게 묻고, 비가 그치기를 기다렸다가 현금으로 계산하세요.',
   -20, 40, 10, 'food,order,tipping,money,weather', 'priya');

-- pr_d8_coffee: Coffee in the fog
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d8_coffee', 1, 'nina',
   'Monday morning. The fog on Lake Avenue is so thick that you hear Nina''s cart before you see it.', '월요일 아침입니다. 레이크 애비뉴에 안개가 짙어서 니나의 카트는 보이기 전에 소리부터 들립니다.',
   'Morning, Priya! Can you believe this fog? I almost walked right past my own cart.', 'Agree: say you could barely see across the street, and that it is supposed to burn off by noon.', '맞장구치세요. 길 건너편이 거의 안 보였다고 하고, 정오쯤이면 걷힌다고 하더라고 하세요.',
   '[{"any":["barely see","burn off","burns off","hardly see"]}]',
   'I know! I could barely see across the street. It''s supposed to burn off by noon.',
   '["I know! I could barely hear the speakerphone. It''s supposed to be fixed by Friday.","I know! I could never finish a whole pizza. It''s supposed to feed four.","I know! I could use a vacation."]',
   '["Fog does not \\"go away\\". It \\"burns off\\" when the sun comes out.","Key words: barely see, supposed to, burn off by noon"]', '["안개는 해가 나면 burn off한다고 말합니다.","핵심 단어: barely see, supposed to, burn off by noon"]',
   'nina', 'Let''s hope so. Nobody can find me in this.', '그러길 바라야죠. 이래서는 아무도 저를 못 찾아요.'),
  ('pr_d8_coffee', 2, 'nina',
   'You have a kickoff call at eleven, and Derek is running the demo. He could use a coffee, too.', '열한 시에 킥오프 콜이 있고, 데모는 데릭이 맡습니다. 데릭에게도 커피가 필요할 것 같습니다.',
   'So, the usual? Medium oat latte, extra shot?', 'Say yes, but make it a large today, and add a drip coffee for your coworker.', '네라고 하되 오늘은 큰 컵으로 달라고 하고, 동료에게 줄 드립 커피도 하나 추가하세요.',
   '[{"any":["large","coworker","colleague","drip coffee"]}]',
   'Yes, but make it a large today. And a drip coffee for my coworker, please.',
   '["Yes, but make it a double room today. And a late checkout, please.","Yes, but make it Thursday. And a window seat, please.","Yes, but make it quick. The bus is coming."]',
   '["Change your usual order with \\"make it a …\\", then add one more drink.","Key words: make it a large, a drip coffee, for my coworker"]', '["\\"make it a …\\"로 평소 주문을 바꾸고, 음료를 하나 더 주문하세요.","핵심 단어: make it a large, a drip coffee, for my coworker"]',
   'nina', 'One large oat latte, one drip. Does your coworker take cream or sugar?', '귀리 우유 라테 큰 컵 하나, 드립 하나. 동료분은 크림이나 설탕 넣어요?'),
  ('pr_d8_coffee', 3, 'nina',
   'Good question. You have no idea how Derek takes his coffee.', '좋은 질문입니다. 데릭이 커피를 어떻게 마시는지 전혀 모릅니다.',
   'Cream? Sugar? Both?', 'Say you are not sure, ask her to leave room for cream, and say you will grab some sugar packets just in case.', '잘 모르겠다고 하고, 크림 넣을 자리를 남겨 달라고 부탁하세요. 혹시 모르니 설탕 봉지도 몇 개 챙기겠다고 하세요.',
   '[{"any":["room for cream","leave room","just in case","sugar packets"]}]',
   'I''m not sure. Could you leave room for cream? I''ll grab some sugar packets just in case.',
   '["I''m not sure. Could you leave the door open? I''ll grab my umbrella on the way out.","I''m not sure. Could you ask the driver? I''ll wait at the back of the bus.","I''m not sure. Could you check the price on the shelf?"]',
   '["\\"Room for cream\\" means the cup is not filled to the top.","Key words: leave room for cream, sugar packets, just in case"]', '["\\"room for cream\\"은 컵을 끝까지 채우지 않고 자리를 남긴다는 뜻입니다.","핵심 단어: leave room for cream, sugar packets, just in case"]',
   'nina', 'Smart. Room for cream it is.', '현명하네요. 크림 자리 남겨 둘게요.'),
  ('pr_d8_coffee', 4, 'nina',
   'Two hot cups, a laptop bag and an umbrella. You only have two hands.', '뜨거운 컵 두 개에 노트북 가방과 우산까지. 손은 둘뿐입니다.',
   'Here you go. How are you going to carry all that?', 'Say that is a good question, and ask for a drink carrier.', '좋은 질문이라고 하고, 음료 캐리어를 달라고 하세요.',
   '[{"any":["carrier","drink tray","cup holder"]}]',
   'Good question. Could I get a drink carrier?',
   '["Good question. Could I get a second opinion?","Good question. Could I get an aisle seat?","Good question. Could I get a later flight?"]',
   '["The cardboard tray that holds several cups is a \\"drink carrier\\".","Key words: could I get, a drink carrier"]', '["컵 여러 개를 담는 종이 받침을 drink carrier라고 합니다.","핵심 단어: could I get, a drink carrier"]',
   'nina', 'Sure thing. That''s eight fifty, so nine twenty with tax.', '그럼요. 8달러 50센트니까, 세금 포함해서 9달러 20센트예요.'),
  ('pr_d8_coffee', 5, 'nina',
   'You tap your card. Nina looks you up and down.', '카드를 갖다 댑니다. 니나가 당신을 위아래로 훑어봅니다.',
   'You''ve got your game face on. Big meeting?', 'Say you are kicking off a new project with a client at eleven, and ask her to wish you luck.', '열한 시에 고객과 새 프로젝트를 시작한다고 하고, 행운을 빌어 달라고 하세요.',
   '[{"any":["kicking off","kick off","kickoff","wish me luck"]}]',
   'We''re kicking off a new project with a client at eleven. Wish me luck!',
   '["We''re running out of oat milk at home. Wish me a happy birthday!","We''re moving to a new apartment on Saturday. Want to help?","We''re closed on Sundays."]',
   '["\\"To kick off\\" a project is to start it, usually with a meeting.","Key words: kicking off, a new project, wish me luck"]', '["프로젝트를 kick off한다는 것은 보통 회의를 열어 시작한다는 뜻입니다.","핵심 단어: kicking off, a new project, wish me luck"]',
   'nina', 'You don''t need luck. But good luck! Careful, they''re hot.', '프리야는 운이 필요 없죠. 그래도 행운을 빌어요! 뜨거우니까 조심하고요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_d8_coffee.barely_see', 'pr_d8_coffee', 'I could barely see across the street.', '길 건너편이 거의 안 보였어요.', '"Barely" = almost not. Also "I could hardly see."', 'barely는 거의 ~하지 못한다는 뜻입니다. "I could hardly see."라고도 합니다.', 'small-talk'),
  ('pr_d8_coffee.burn_off', 'pr_d8_coffee', 'It''s supposed to burn off by noon.', '정오쯤이면 걷힌대요.', 'Fog "burns off" as the sun warms the air. "Supposed to" = that is what the forecast says.', '해가 공기를 데우면 안개가 burn off합니다. supposed to는 예보가 그렇다는 뜻입니다.', 'small-talk'),
  ('pr_d8_coffee.make_it_a_large', 'pr_d8_coffee', 'Make it a large today.', '오늘은 큰 걸로 주세요.', '"Make it a …" changes an order that was just said.', '"Make it a …"는 방금 나온 주문을 바꿀 때 씁니다.', 'food'),
  ('pr_d8_coffee.room_for_cream', 'pr_d8_coffee', 'Could you leave room for cream?', '크림 넣을 자리를 남겨 주시겠어요?', 'Baristas often ask "Room for cream?" Answer "Yes, please" or "No, fill it up."', '바리스타가 "Room for cream?" 하고 자주 묻습니다. "Yes, please"나 "No, fill it up."으로 답합니다.', 'food'),
  ('pr_d8_coffee.just_in_case', 'pr_d8_coffee', 'I''ll grab some sugar packets just in case.', '혹시 모르니 설탕 봉지를 몇 개 챙길게요.', '"Just in case" = because it might be needed.', 'just in case는 필요할지도 모르니까라는 뜻입니다.', 'small-talk'),
  ('pr_d8_coffee.drink_carrier', 'pr_d8_coffee', 'Could I get a drink carrier?', '음료 캐리어 하나 주시겠어요?', 'The cardboard tray for two or four cups. Free at most coffee shops.', '컵 두 개나 네 개를 담는 종이 받침입니다. 대부분의 커피 가게에서 무료로 줍니다.', 'food'),
  ('pr_d8_coffee.kicking_off', 'pr_d8_coffee', 'We''re kicking off a new project.', '새 프로젝트를 시작해요.', 'From football. The first meeting of a project is "the kickoff".', '미식축구에서 온 말입니다. 프로젝트의 첫 회의를 the kickoff라고 합니다.', 'meeting'),
  ('pr_d8_coffee.game_face', 'pr_d8_coffee', 'You''ve got your game face on.', '단단히 마음먹은 얼굴이네요.', 'A serious, ready look before something important.', '중요한 일을 앞두고 각오를 다진 진지한 표정을 말합니다.', 'small-talk');

-- pr_d8_prep: Prepping the team for the kickoff
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d8_prep', 1, 'derek',
   'Standup is at nine thirty this week to make room for the client calls. Afterwards Derek and Jun roll their chairs over.', '고객 통화 시간을 내려고 이번 주 스탠드업은 9시 30분입니다. 끝난 뒤 데릭과 준이 의자를 끌고 옵니다.',
   'So, eleven o''clock with Summit Retail. What''s the plan?', 'Give them the game plan: the checkout demo first, then the dashboard project, then next steps.', '진행 계획을 알려 주세요. 먼저 결제 화면 데모, 다음은 대시보드 프로젝트, 그다음은 다음 단계입니다.',
   '[{"any":["game plan","demo first"]},{"all":["demo","dashboard"]}]',
   'Here''s the game plan: the checkout demo first, then the dashboard project, then next steps.',
   '["Here''s the menu: the soup first, then the grilled cheese, then the pie.","Here''s the route: Lake Avenue first, then Cedar Street, then the park.","Here''s the receipt: the eggs first, then the milk."]',
   '["A \\"game plan\\" is the plan for how you will handle something. Give three steps.","Key words: game plan, the checkout demo first, then, next steps"]', '["game plan은 일을 어떻게 풀어 갈지에 대한 계획입니다. 세 단계로 말하세요.","핵심 단어: game plan, the checkout demo first, then, next steps"]',
   'derek', 'Short and sweet. I like it.', '짧고 분명하네요. 마음에 들어요.'),
  ('pr_d8_prep', 2, 'derek',
   'Three people on one call. Everyone needs a job.', '한 통화에 세 사람이 들어갑니다. 저마다 맡을 일이 있어야 합니다.',
   'So who''s doing what?', 'Say Derek runs the demo, Jun takes the technical questions, and you will open and close.', '데릭이 데모를 맡고, 준이 기술 질문을 받고, 시작과 마무리는 당신이 하겠다고 하세요.',
   '[{"any":["technical questions","open and close","run the demo"]}]',
   'Derek, you run the demo. Jun, you take the technical questions. I''ll open and close.',
   '["Derek, you get the door. Jun, you take the elevator. I''ll park the car.","Derek, you wash the dishes. Jun, you take out the trash. I''ll cook.","Derek, you sit by the window."]',
   '["Give each person one job: \\"You run …\\", \\"You take …\\", \\"I''ll …\\".","Key words: you run the demo, you take the technical questions, I''ll open and close"]', '["사람마다 일을 하나씩 주세요. \\"You run …\\", \\"You take …\\", \\"I''ll …\\".","핵심 단어: you run the demo, you take the technical questions, I''ll open and close"]',
   'jun', 'Technical questions. Okay. But what if Greg asks something I can''t answer?', '기술 질문이요. 알겠습니다. 그런데 그렉이 제가 대답 못 할 걸 물으면요?'),
  ('pr_d8_prep', 3, 'jun',
   'It is Jun''s first call with a client. He is turning his pen over and over.', '준에게는 고객과의 첫 통화입니다. 펜을 자꾸 돌리고 있습니다.',
   'I don''t want to make something up and get it wrong.', 'Tell him to say "I don''t know, but I''ll find out." Greg respects that.', '"I don''t know, but I''ll find out."이라고 하면 된다고 알려 주세요. 그렉은 그런 답을 높이 삽니다.',
   '[{"any":["find out","look into it"]}]',
   'Then say, "I don''t know, but I''ll find out." Greg respects that.',
   '["Then say, \\"I don''t eat meat, but I''ll have the soup.\\" Rosa respects that.","Then say, \\"I don''t have cash, but I''ll pay by card.\\" Mike is fine with that.","Then say nothing and leave the room."]',
   '["An honest \\"I don''t know\\" plus a promise is better than a guess.","Key words: I don''t know, but I''ll find out"]', '["짐작으로 답하는 것보다, 모른다고 솔직히 말하고 알아보겠다고 약속하는 편이 낫습니다.","핵심 단어: I don''t know, but I''ll find out"]',
   'jun', 'That I can do.', '그건 할 수 있어요.'),
  ('pr_d8_prep', 4, 'derek',
   'Derek has been on calls with Greg before.', '데릭은 전에도 그렉과 통화해 본 적이 있습니다.',
   'And what if he brings up money? He always brings up money.', 'Ask them to let you do the talking on pricing, and to send anything about money your way.', '가격 이야기는 당신이 하게 해 달라고 하고, 돈 이야기가 나오면 당신에게 넘기라고 하세요.',
   '[{"any":["do the talking","send it my way","leave the pricing","leave pricing"]}]',
   'Let me do the talking on pricing. If money comes up, just send it my way.',
   '["Let me do the dishes tonight. If the phone rings, just let it ring.","Let me do the driving on the highway. If you get tired, just take a nap.","Let me do the shopping this week."]',
   '["\\"Let me do the talking\\" = I will be the one who speaks about this.","Key words: let me do the talking, on pricing, send it my way"]', '["\\"Let me do the talking\\"은 그 이야기는 내가 하겠다는 뜻입니다.","핵심 단어: let me do the talking, on pricing, send it my way"]',
   'derek', 'Gladly. I write code, not invoices.', '기꺼이요. 저는 코드를 쓰지 청구서를 쓰지는 않으니까요.'),
  ('pr_d8_prep', 5, 'jun',
   'Jun writes "pricing = Priya" in his notebook and underlines it twice.', '준이 공책에 "가격 = 프리야"라고 쓰고 밑줄을 두 번 긋습니다.',
   'Is there anything we shouldn''t say?', 'Say: do not commit to any dates on the call. If Greg pushes, say you will follow up in writing.', '통화 중에는 어떤 날짜도 약속하지 말라고 하세요. 그렉이 밀어붙이면 글로 정리해서 답하겠다고 말하라고요.',
   '[{"any":["commit to","in writing","promise any"]}]',
   'Don''t commit to any dates on the call. If he pushes, say we''ll follow up in writing.',
   '["Don''t leave any food on the table. If it rains, take my umbrella.","Don''t park on Lake Avenue on Mondays. If you do, they''ll tow your car.","Don''t forget your badge tomorrow."]',
   '["\\"To commit to\\" a date is to promise it. Tell them what to say instead.","Key words: don''t commit to any dates, follow up in writing"]', '["날짜에 commit한다는 것은 그 날짜를 약속한다는 뜻입니다. 대신 뭐라고 말할지도 알려 주세요.","핵심 단어: don''t commit to any dates, follow up in writing"]',
   'derek', 'No dates, no dollars. Got it. See you in there at five to eleven.', '날짜 얘기도, 돈 얘기도 안 하기. 알겠어요. 10시 55분에 회의실에서 봐요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_d8_prep.game_plan', 'pr_d8_prep', 'Here''s the game plan.', '진행 계획은 이래요.', 'A sports word for a plan of action. Common before a client meeting.', '스포츠에서 온 말로 행동 계획을 뜻합니다. 고객 회의 전에 자주 씁니다.', 'meeting'),
  ('pr_d8_prep.short_and_sweet', 'pr_d8_prep', 'Short and sweet.', '짧고 분명하네요.', 'Pleasantly brief. A compliment for a plan, a meeting or an email.', '짧아서 좋다는 뜻입니다. 계획이나 회의, 이메일을 칭찬할 때 씁니다.', 'office'),
  ('pr_d8_prep.run_the_demo', 'pr_d8_prep', 'You run the demo.', '데모는 당신이 맡아요.', 'Giving roles before a call: "You run …", "You take …", "You cover …".', '통화 전에 역할을 나눌 때 "You run …", "You take …", "You cover …"라고 합니다.', 'meeting'),
  ('pr_d8_prep.open_and_close', 'pr_d8_prep', 'I''ll open and close.', '시작과 마무리는 제가 할게요.', 'The person who opens and closes a meeting leads it.', '회의를 열고 닫는 사람이 그 회의를 이끄는 사람입니다.', 'meeting'),
  ('pr_d8_prep.find_out', 'pr_d8_prep', 'I don''t know, but I''ll find out.', '모르겠지만 알아보겠습니다.', 'Clients trust this more than a confident guess.', '고객은 자신 있게 하는 짐작보다 이 말을 더 믿습니다.', 'office'),
  ('pr_d8_prep.do_the_talking', 'pr_d8_prep', 'Let me do the talking on pricing.', '가격 이야기는 제가 할게요.', 'One voice on money keeps the team from saying two different numbers.', '돈 이야기를 한 사람이 맡아야 팀에서 서로 다른 숫자가 나오지 않습니다.', 'meeting'),
  ('pr_d8_prep.send_it_my_way', 'pr_d8_prep', 'Just send it my way.', '저한테 넘기세요.', '"Send it my way" = pass it to me. Also used for emails and questions.', 'send it my way는 나에게 넘기라는 뜻입니다. 이메일이나 질문에도 씁니다.', 'office'),
  ('pr_d8_prep.dont_commit', 'pr_d8_prep', 'Don''t commit to any dates on the call.', '통화 중에는 어떤 날짜도 약속하지 마세요.', '"Commit to" = promise. What is said on a call is hard to take back.', 'commit to는 약속한다는 뜻입니다. 통화에서 한 말은 되돌리기 어렵습니다.', 'meeting');

-- pr_d8_kickoff: Running the kickoff call
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d8_kickoff', 1, 'greg',
   'Eleven o''clock. The fog has lifted. Greg Whitfield appears on the big screen with two people beside him.', '열한 시입니다. 안개가 걷혔습니다. 큰 화면에 그렉 휫필드가 두 사람과 함께 나타납니다.',
   'Morning, Priya. I''ve got my team here, and a hard stop at noon.', 'Thank everyone for making the time, and suggest a quick round of introductions.', '시간을 내 줘서 고맙다고 하고, 짧게 돌아가며 소개하자고 하세요.',
   '[{"any":["introductions","making the time","introduce ourselves"]}]',
   'Thanks for making the time, everyone. Let''s do a quick round of introductions.',
   '["Thanks for making the soup, everyone. Let''s do a quick lap around the park.","Thanks for holding the elevator, everyone. Let''s take the stairs next time.","Thanks for the ride, everyone."]',
   '["Thank them, then ask everyone to say who they are.","Key words: thanks for making the time, a quick round of introductions"]', '["고맙다고 한 뒤, 저마다 자신을 소개하게 하세요.","핵심 단어: thanks for making the time, a quick round of introductions"]',
   'greg', 'Sure. I''m Greg, VP of operations. With me are Dana from IT and Luis from finance.', '그러죠. 저는 운영 담당 부사장 그렉입니다. 옆에는 IT의 데이나와 재무의 루이스가 있습니다.'),
  ('pr_d8_kickoff', 2, 'greg',
   'Derek and Jun sit on either side of you.', '데릭과 준이 당신의 양옆에 앉아 있습니다.',
   'And who do we have on your side?', 'Introduce Derek, your senior developer, and Jun, who will be building most of the dashboard.', '시니어 개발자 데릭과, 대시보드의 대부분을 만들 준을 소개하세요.',
   '[{"any":["on our side","senior developer","building most"]}]',
   'On our side, this is Derek, our senior developer, and Jun, who''ll be building most of the dashboard.',
   '["On our street, this is the bakery, and that''s the bus stop.","On our menu, this is the veggie omelet, and that''s the club sandwich.","On our floor, the printer is by the kitchen."]',
   '["Name, then role: \\"This is …, our …\\".","Key words: on our side, this is, our senior developer, building the dashboard"]', '["이름을 말하고 역할을 덧붙이세요. \\"This is …, our …\\".","핵심 단어: on our side, this is, our senior developer, building the dashboard"]',
   'jun', 'Hi, Greg. Nice to meet you. I''m looking forward to working with you.', '안녕하세요, 그렉. 만나서 반갑습니다. 함께 일하게 되어 기대됩니다.'),
  ('pr_d8_kickoff', 3, 'greg',
   'Greg looks at his watch. One hour, no more.', '그렉이 시계를 봅니다. 주어진 시간은 딱 한 시간입니다.',
   'Likewise. So what''s the plan for the hour?', 'Say you have three items on the agenda: the checkout demo, his goals for the dashboard, and next steps.', '안건이 세 가지라고 하세요. 결제 화면 데모, 대시보드에 대한 그렉의 목표, 그리고 다음 단계입니다.',
   '[{"any":["agenda","three items","three things"]}]',
   'We have three items on the agenda: the checkout demo, your goals for the dashboard, and next steps.',
   '["We have three kinds of pie today: apple, cherry, and pecan.","We have three buses an hour: the 12, the 14, and the express.","We have three eggs left in the fridge."]',
   '["Say how many items there are, then list them.","Key words: three items on the agenda, demo, goals, next steps"]', '["안건이 몇 개인지 말한 뒤 하나씩 말하세요.","핵심 단어: three items on the agenda, demo, goals, next steps"]',
   'greg', 'Works for me. Show me the demo.', '좋습니다. 데모를 보여 주세요.');

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d8_kickoff', 4, 'greg',
   'Derek''s demo of the new checkout runs without a hitch. Greg''s team claps.', '데릭의 새 결제 화면 데모가 매끄럽게 끝납니다. 그렉의 팀이 박수를 칩니다.',
   'Nice. My team loved it. Now, the dashboard. Where do you want to start?', 'Start with the goal: ask what success looks like for him six months from now.', '목표부터 시작하세요. 6개월 뒤에 어떤 모습이면 성공인지 물어보세요.',
   '[{"all":["success"]}]',
   'Let''s start with the goal. What does success look like for you six months from now?',
   '["Let''s start with the salad. What does the soup of the day come with?","Let''s start with your address. What does the landlord charge for parking?","Let''s start with the top shelf."]',
   '["Do not ask about features first. Ask what a good result would be.","Key words: what does success look like, six months from now"]', '["기능부터 묻지 말고, 어떤 결과가 나오면 좋은지 물어보세요.","핵심 단어: what does success look like, six months from now"]',
   'greg', 'Simple. Our store managers are flying blind. I want live inventory for all forty stores on one screen.', '간단합니다. 우리 매장 관리자들은 정보 없이 감으로 일하고 있어요. 40개 매장의 실시간 재고를 한 화면에서 보고 싶습니다.'),
  ('pr_d8_kickoff', 5, 'greg',
   'Jun asks how the stores send their data and explains that nightly files will not be enough. Greg nods.', '준이 매장에서 데이터를 어떻게 보내는지 묻고, 밤마다 올리는 파일로는 부족하다고 설명합니다. 그렉이 고개를 끄덕입니다.',
   'Fine. You''ll have API access by Wednesday. What else do you need from me?', 'Ask for a single point of contact on his side, so that decisions do not get stuck.', '결정이 막히지 않도록 그쪽에서 담당자 한 명을 정해 달라고 하세요.',
   '[{"any":["point of contact","one person","decision maker"]}]',
   'One thing: a single point of contact on your side, so decisions don''t get stuck.',
   '["One thing: a single room on the top floor, so the noise doesn''t wake me up.","One thing: a single scoop of vanilla, so the pie doesn''t feel lonely.","One thing: a bigger umbrella."]',
   '["Ask for one person who can answer questions and say yes or no.","Key words: a single point of contact, on your side, decisions"]', '["질문에 답하고 결정을 내려 줄 수 있는 사람 한 명을 부탁하세요.","핵심 단어: a single point of contact, on your side, decisions"]',
   'greg', 'That''s Dana. She has the authority to say yes or no.', '데이나가 맡을 겁니다. 결정할 권한이 있어요.'),
  ('pr_d8_kickoff', 6, 'greg',
   'The clock says 11:55. Greg starts to gather his papers.', '시계가 11시 55분을 가리킵니다. 그렉이 서류를 챙기기 시작합니다.',
   'Five minutes. Where does that leave us?', 'Play it back: API access by Wednesday, Dana is the point of contact, and scope tomorrow at ten thirty.', '정리해서 되짚으세요. 수요일까지 API 접근 권한, 담당자는 데이나, 범위 논의는 내일 10시 30분입니다.',
   '[{"any":["play that back","play it back"]},{"all":["wednesday","tomorrow"]}]',
   'Let me play that back: API access by Wednesday, Dana is our point of contact, and we talk scope tomorrow at ten thirty.',
   '["Let me play that song again: it was on the radio at the diner this morning.","Let me pay for that: two coffees, one muffin, and a bottle of water.","Let me sleep on it."]',
   '["\\"Play it back\\" = repeat what was agreed so that everyone hears the same thing.","Key words: let me play that back, by Wednesday, point of contact, tomorrow at ten thirty"]', '["play it back은 합의한 내용을 되짚어 모두가 같은 내용을 듣게 하는 것입니다.","핵심 단어: let me play that back, by Wednesday, point of contact, tomorrow at ten thirty"]',
   'greg', 'That''s it. And one minute early. Talk tomorrow.', '맞습니다. 게다가 1분 일찍 끝났네요. 내일 이야기합시다.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_d8_kickoff.making_the_time', 'pr_d8_kickoff', 'Thanks for making the time.', '시간 내 주셔서 감사합니다.', '"Make the time" = find time in a busy schedule. A polite opening with clients.', 'make the time은 바쁜 일정 중에 시간을 낸다는 뜻입니다. 고객과의 회의를 여는 공손한 말입니다.', 'meeting'),
  ('pr_d8_kickoff.hard_stop', 'pr_d8_kickoff', 'I have a hard stop at noon.', '정오에는 꼭 끝내야 해요.', 'The meeting must end at that time, no matter what. Plan your agenda around it.', '무슨 일이 있어도 그 시간에는 끝내야 한다는 뜻입니다. 안건을 거기에 맞추세요.', 'meeting'),
  ('pr_d8_kickoff.round_of_introductions', 'pr_d8_kickoff', 'Let''s do a quick round of introductions.', '짧게 돌아가며 소개합시다.', 'Everyone says their name and role, one after the other.', '참석자가 차례로 이름과 역할을 말하는 것입니다.', 'meeting'),
  ('pr_d8_kickoff.on_our_side', 'pr_d8_kickoff', 'On our side, this is Derek.', '저희 쪽에서는 이 사람이 데릭입니다.', '"On our side" / "on your side" = on our team / on your team in a deal.', 'on our side, on your side는 거래에서 우리 쪽, 그쪽을 가리킵니다.', 'meeting'),
  ('pr_d8_kickoff.items_on_the_agenda', 'pr_d8_kickoff', 'We have three items on the agenda.', '안건이 세 가지 있습니다.', 'Saying the number first helps people follow along.', '개수를 먼저 말하면 듣는 사람이 따라오기 쉽습니다.', 'meeting'),
  ('pr_d8_kickoff.success_look_like', 'pr_d8_kickoff', 'What does success look like for you?', '어떤 모습이면 성공이라고 보세요?', 'Asks for the goal behind the request. A favorite question of product managers.', '요청 뒤에 있는 목표를 묻는 말입니다. 프로덕트 매니저가 즐겨 쓰는 질문입니다.', 'meeting'),
  ('pr_d8_kickoff.point_of_contact', 'pr_d8_kickoff', 'a single point of contact', '단일 연락 담당자', 'The one person you go to with questions. Often shortened to POC.', '질문이 있을 때 찾는 한 사람입니다. 흔히 POC로 줄여 씁니다.', 'office'),
  ('pr_d8_kickoff.play_that_back', 'pr_d8_kickoff', 'Let me play that back.', '제가 다시 정리해 볼게요.', 'Like replaying a recording: you repeat what you heard to check it.', '녹음을 다시 트는 것처럼, 들은 내용을 되풀이해 확인하는 말입니다.', 'meeting');

-- pr_d9_scope: The wish list: saying "not yet"
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d9_scope', 1, 'greg',
   'Rain runs down the meeting room window. You sent Greg the gift card update this morning, as promised. Now he is back on the screen, and he sounds rushed.', '회의실 창문에 빗물이 흘러내립니다. 약속한 대로 오늘 아침 그렉에게 기프트 카드 진행 상황을 보냈습니다. 그렉이 다시 화면에 나타났는데, 급한 기색입니다.',
   'Our board wants the dashboard and the mobile app live by November first. And while you''re at it, the wish list.', 'Do not say no. Say you hear him, and suggest looking at what has to be live on November first and what can follow.', '안 된다고 하지 마세요. 무슨 말인지 알겠다고 하고, 11월 1일에 꼭 나가야 하는 것과 뒤따라가도 되는 것을 같이 보자고 하세요.',
   '[{"any":["i hear you","can follow","has to be live"]}]',
   'I hear you. Let''s look at what has to be live on November first, and what can follow.',
   '["I see you. Let''s look at what has to be in the fridge by Sunday.","I miss you. Let''s look at flights for November first.","I owe you. Let''s get lunch."]',
   '["\\"I hear you\\" shows you understand, without agreeing.","Key words: I hear you, has to be live, what can follow"]', '["\\"I hear you\\"는 동의하지는 않으면서 이해했다는 것을 보여 줍니다.","핵심 단어: I hear you, has to be live, what can follow"]',
   'greg', 'Everything has to be live. That''s what I told the board.', '전부 나가야 합니다. 이사회에 그렇게 말했어요.'),
  ('pr_d9_scope', 2, 'greg',
   'The dashboard alone is eight weeks of work. The mobile app is another eight.', '대시보드만 해도 8주가 걸립니다. 모바일 앱은 8주가 더 필요합니다.',
   'So what can you realistically deliver by November first?', 'Propose two phases: phase one is the dashboard on November first, phase two is the mobile app in January.', '두 단계를 제안하세요. 1단계는 11월 1일의 대시보드, 2단계는 1월의 모바일 앱입니다.',
   '[{"any":["phase one","phase two","i would propose"]}]',
   'Here''s what I''d propose: phase one is the dashboard on November first. Phase two is the mobile app, in January.',
   '["Here''s what I''d order: the soup is the best thing on the menu. The pie is second.","Here''s what I''d wear: a jacket in the morning. A raincoat in the afternoon.","Here''s what I''d skip: dessert."]',
   '["Open with \\"Here''s what I''d propose\\", then give each phase a date.","Key words: here''s what I''d propose, phase one, phase two, January"]', '["\\"Here''s what I''d propose\\"로 시작하고, 단계마다 날짜를 붙이세요.","핵심 단어: here''s what I''d propose, phase one, phase two, January"]',
   'greg', 'Phased… okay, I could sell that to the board. But the wish list goes into phase one, right? It''s a tiny feature.', '단계별이라… 좋아요, 그거면 이사회를 설득할 수 있겠어요. 그런데 위시리스트는 1단계에 들어가는 거죠? 아주 작은 기능이잖아요.'),
  ('pr_d9_scope', 3, 'greg',
   'It is not tiny. Derek''s estimate for the wish list was three weeks.', '작지 않습니다. 데릭이 추정한 위시리스트 작업은 3주였습니다.',
   'Come on. It''s just a button.', 'Say you would love to get to it and it is on the roadmap, but adding it now would put November first at risk.', '꼭 하고 싶고 로드맵에도 있지만, 지금 넣으면 11월 1일이 위험해진다고 하세요.',
   '[{"any":["at risk","on the roadmap","jeopardize"]}]',
   'I''d love to get to it, and it''s on the roadmap. But adding it now would put November first at risk.',
   '["I''d love to get a dog, and it''s on my list. But my building doesn''t allow pets.","I''d love to stay for dessert. But my bus leaves in five minutes.","I''d love a refill."]',
   '["Yes to the idea, no to the timing: say what the cost would be.","Key words: I''d love to, on the roadmap, put November first at risk"]', '["아이디어에는 찬성하되 시기에는 반대하세요. 지금 하면 무엇을 잃는지 말합니다.","핵심 단어: I''d love to, on the roadmap, put November first at risk"]',
   'greg', 'I can''t move November first.', '11월 1일은 옮길 수 없어요.');

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d9_scope', 4, 'greg',
   'Greg leans back and crosses his arms.', '그렉이 의자에 기대며 팔짱을 낍니다.',
   'So you''re telling me no.', 'Say it is not a no, it is a not yet, and offer to put the wish list at the top of phase two.', '안 된다는 게 아니라 아직은 아니라는 뜻이라고 하고, 위시리스트를 2단계의 맨 위에 두겠다고 제안하세요.',
   '[{"any":["not yet","top of phase two"]}]',
   'It''s not a no. It''s a not yet. We can put the wish list at the top of phase two.',
   '["It''s not a bus. It''s a shuttle. We can put the bags in the back.","It''s not a latte. It''s a cappuccino. We can make you another one.","It''s not a holiday. We''re open."]',
   '["Turn \\"no\\" into \\"not yet\\", and say exactly when.","Key words: not a no, a not yet, at the top of phase two"]', '["\\"no\\"를 \\"not yet\\"으로 바꾸고, 정확히 언제 할지 말하세요.","핵심 단어: not a no, a not yet, at the top of phase two"]',
   'greg', 'Top of phase two. Hmm. And what if I want it sooner anyway?', '2단계의 맨 위라. 흠. 그래도 더 빨리 받고 싶다면요?'),
  ('pr_d9_scope', 5, 'greg',
   'He tries one more time. You give him the choice instead of the answer.', '그렉이 한 번 더 밀어붙입니다. 당신은 답 대신 선택지를 줍니다.',
   'It''s my money. Put it in phase one.', 'Say that if the wish list comes in, something has to come out, and ask which he would rather have on November first.', '위시리스트가 들어오면 무언가는 빠져야 한다고 하고, 11월 1일에 어느 쪽을 받고 싶은지 물어보세요.',
   '[{"any":["come out","would you rather","comes out"]}]',
   'If the wish list comes in, something has to come out. Which would you rather have on November first?',
   '["If the rain comes in, the chairs have to go inside. Which door is open?","If the bus comes late, we have to walk. Which way is downtown?","If the cat comes in, the dog goes out."]',
   '["Show the trade, then let the client choose.","Key words: something has to come out, which would you rather"]', '["맞바꿔야 하는 것을 보여 주고, 고객이 고르게 하세요.","핵심 단어: something has to come out, which would you rather"]',
   'greg', 'The dashboard. No question. Fine, you win. Phase two.', '대시보드죠. 말할 것도 없어요. 좋아요, 당신이 이겼어요. 2단계로 합시다.'),
  ('pr_d9_scope', 6, 'greg',
   'Jun is taking notes as fast as he can.', '준이 있는 힘껏 받아 적고 있습니다.',
   'So what am I telling my board?', 'Confirm: the dashboard live on November first, the mobile app and the wish list in January, and an updated timeline tomorrow.', '확인해 주세요. 대시보드는 11월 1일에 나가고, 모바일 앱과 위시리스트는 1월이며, 수정된 일정은 내일 보내겠다고요.',
   '[{"all":["november"],"any":["january","timeline"]}]',
   'Dashboard live on November first, mobile app and wish list in January. You''ll have the updated timeline tomorrow.',
   '["Peaches in August, apples in October. You''ll have the pumpkins next month.","Breakfast until eleven, lunch until three. You''ll have the check in a minute.","Rain today, sun on Saturday."]',
   '["Give him one sentence he can repeat to his board, then the next step.","Key words: live on November first, in January, the updated timeline tomorrow"]', '["그렉이 이사회에 그대로 전할 수 있는 한 문장을 주고, 다음 단계를 말하세요.","핵심 단어: live on November first, in January, the updated timeline tomorrow"]',
   'greg', 'Sounds like a plan. Thanks for being straight with me.', '좋은 계획이네요. 솔직하게 말해 줘서 고마워요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_d9_scope.while_youre_at_it', 'pr_d9_scope', 'And while you''re at it, the wish list.', '하는 김에 위시리스트도요.', 'How extra work gets added: "since you are already doing that, do this too."', '일이 덧붙는 전형적인 말입니다. 어차피 하는 김에 이것도 해 달라는 뜻입니다.', 'meeting'),
  ('pr_d9_scope.i_hear_you', 'pr_d9_scope', 'I hear you.', '무슨 말씀인지 알겠어요.', 'Shows you understand how the other person feels. It does not mean "I agree".', '상대의 마음을 이해한다는 말입니다. 동의한다는 뜻은 아닙니다.', 'meeting'),
  ('pr_d9_scope.what_id_propose', 'pr_d9_scope', 'Here''s what I''d propose.', '제가 제안하고 싶은 건 이렇습니다.', '"I''d propose" is softer than "I propose". It invites discussion.', 'I''d propose는 I propose보다 부드럽고, 논의의 여지를 남깁니다.', 'meeting'),
  ('pr_d9_scope.at_risk', 'pr_d9_scope', 'That would put November first at risk.', '그러면 11월 1일이 위험해집니다.', '"Put something at risk" = make it likely to fail. Name the thing the client cares about.', 'put something at risk는 그것이 실패할 가능성을 높인다는 뜻입니다. 고객이 아끼는 것을 짚어 말하세요.', 'meeting'),
  ('pr_d9_scope.not_yet', 'pr_d9_scope', 'It''s not a no. It''s a not yet.', '안 된다는 게 아니라 아직은 아니라는 거예요.', 'Keeps the idea alive and the relationship warm.', '아이디어도 살리고 관계도 지키는 말입니다.', 'meeting'),
  ('pr_d9_scope.top_of_phase_two', 'pr_d9_scope', 'We can put it at the top of phase two.', '2단계의 맨 위에 둘 수 있어요.', '"At the top of" a list = the first thing to be done.', 'at the top of는 목록에서 가장 먼저 할 일이라는 뜻입니다.', 'meeting'),
  ('pr_d9_scope.something_has_to_come_out', 'pr_d9_scope', 'If the wish list comes in, something has to come out.', '위시리스트가 들어오면 무언가는 빠져야 해요.', 'The rule of a fixed date: new work replaces old work.', '날짜가 고정되어 있을 때의 원칙입니다. 새 일이 들어오면 있던 일이 빠집니다.', 'meeting'),
  ('pr_d9_scope.would_you_rather', 'pr_d9_scope', 'Which would you rather have?', '어느 쪽을 받고 싶으세요?', '"Would rather" = prefer. Giving a choice is easier to accept than a no.', 'would rather는 더 좋아한다는 뜻입니다. 거절보다 선택지가 받아들이기 쉽습니다.', 'meeting');

-- pr_d9_actions: Nailing down the action items
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d9_actions', 1, 'jun',
   'It is still raining. Jun is at his desk with three pages of notes from the call.', '비가 아직도 옵니다. 준이 통화에서 적은 메모 세 장을 들고 자리에 앉아 있습니다.',
   'That was intense. I wrote down everything, but I''m not sure who''s doing what.', 'Suggest nailing down the action items now, while the call is still fresh.', '통화 내용이 생생할 때 지금 액션 아이템을 확실히 정하자고 하세요.',
   '[{"any":["nail down","fresh","pin down"]}]',
   'Let''s nail down the action items while it''s still fresh.',
   '["Let''s eat the bread while it''s still warm.","Let''s catch the bus while it''s still dry out.","Let''s go home."]',
   '["\\"Nail down\\" = make something definite. Do it right after the meeting.","Key words: nail down, the action items, while it''s still fresh"]', '["nail down은 확실히 정한다는 뜻입니다. 회의가 끝난 직후에 하세요.","핵심 단어: nail down, the action items, while it''s still fresh"]',
   'jun', 'Good idea. I have three so far.', '좋은 생각이에요. 지금까지 세 가지예요.'),
  ('pr_d9_actions', 2, 'jun',
   'Jun turns to the first page.', '준이 첫 장을 펼칩니다.',
   'First, the updated timeline for Greg. Is that mine?', 'Say you will take that one, and that Greg will have it by noon tomorrow.', '그건 당신이 맡겠다고 하고, 내일 정오까지 그렉에게 보내겠다고 하세요.',
   '[{"any":["i will take that","noon tomorrow","that one is mine"]}]',
   'I''ll take that one. Greg will have it by noon tomorrow.',
   '["I''ll take the stairs. The elevator is acting up again.","I''ll take a dozen eggs. The large ones, please.","I''ll take a nap."]',
   '["Claim the task, then give the day and the time.","Key words: I''ll take that one, by noon tomorrow"]', '["일을 맡겠다고 하고, 날짜와 시간을 말하세요.","핵심 단어: I''ll take that one, by noon tomorrow"]',
   'jun', 'Okay. Timeline: Priya, noon tomorrow.', '네. 일정표: 프리야, 내일 정오.'),
  ('pr_d9_actions', 3, 'jun',
   'Jun flies to Ridgeport on Thursday morning.', '준은 목요일 아침에 리지포트로 떠납니다.',
   'Second, the estimate for the wish list in phase two.', 'Ask if he can own that one. A rough estimate is fine, but you need it before he flies out on Thursday.', '그건 준이 맡아 줄 수 있는지 물어보세요. 대략적인 추정치면 되지만, 목요일에 출발하기 전에 필요하다고 하세요.',
   '[{"any":["rough estimate","ballpark","own that"]}]',
   'Can you own that one? A rough estimate is fine, but I need it before you fly out on Thursday.',
   '["Can you open that window? A little air is fine, but I need my jacket.","Can you hold that door? A second is fine, but I need both hands.","Can you hear that?"]',
   '["Ask him to be the owner, say how exact it must be, and give the deadline.","Key words: can you own that one, a rough estimate, before you fly out"]', '["담당자가 되어 달라고 하고, 얼마나 정확해야 하는지와 기한을 말하세요.","핵심 단어: can you own that one, a rough estimate, before you fly out"]',
   'jun', 'Sure. I''ll sit down with Derek this afternoon.', '그럼요. 오늘 오후에 데릭과 같이 앉아서 볼게요.'),
  ('pr_d9_actions', 4, 'derek',
   'Derek walks by with a mug of coffee and looks over Jun''s shoulder.', '데릭이 커피 잔을 들고 지나가다 준의 어깨 너머로 메모를 봅니다.',
   'Don''t forget the API access. Greg promised it by tomorrow, and nobody''s chasing it.', 'Say he is right, and that you will follow up with Dana first thing tomorrow.', '맞는 말이라고 하고, 내일 아침 가장 먼저 데이나에게 확인하겠다고 하세요.',
   '[{"any":["follow up","first thing","check in with"]}]',
   'You''re right. I''ll follow up with Dana first thing tomorrow.',
   '["You''re right. I''ll have the salad with the dressing on the side.","You''re right. I''ll bring an umbrella from now on.","You''re right. I''ll turn left at the fountain."]',
   '["\\"Follow up with\\" a person = contact them again to check on a promise.","Key words: follow up with Dana, first thing tomorrow"]', '["누구에게 follow up한다는 것은 약속한 일을 확인하려고 다시 연락한다는 뜻입니다.","핵심 단어: follow up with Dana, first thing tomorrow"]',
   'derek', 'Perfect. No access, no dashboard.', '좋아요. 접근 권한이 없으면 대시보드도 없으니까요.'),
  ('pr_d9_actions', 5, 'jun',
   'Three items, three owners. Jun opens a new email.', '세 가지 일에 담당자도 셋입니다. 준이 새 이메일 창을 엽니다.',
   'Should I send these notes to everyone?', 'Say yes: today, with an owner and a due date next to each item, and ask him to cc Maya.', '네라고 하세요. 오늘 보내되 항목마다 담당자와 기한을 적고, 마야를 참조로 넣어 달라고 하세요.',
   '[{"any":["due date","cc maya","an owner"]}]',
   'Yes, please send them out today, with an owner and a due date next to each item. And cc Maya.',
   '["Yes, please send them back today, with the receipt in the box. And keep the tag on.","Yes, please put them in the fridge, with the milk on the bottom shelf.","Yes, please sit anywhere."]',
   '["An action item has three parts: the task, the owner, the due date.","Key words: send them out today, an owner, a due date, cc Maya"]', '["액션 아이템은 할 일, 담당자, 기한의 세 부분으로 이루어집니다.","핵심 단어: send them out today, an owner, a due date, cc Maya"]',
   'jun', 'Owner, due date, cc Maya. They''ll go out within the hour.', '담당자, 기한, 마야 참조. 한 시간 안에 보낼게요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_d9_actions.nail_down', 'pr_d9_actions', 'Let''s nail down the action items.', '액션 아이템을 확실히 정합시다.', '"Nail down" = make final and clear. You can nail down a date, a price or a plan.', 'nail down은 분명하게 확정한다는 뜻입니다. 날짜, 가격, 계획에 두루 씁니다.', 'meeting'),
  ('pr_d9_actions.while_its_fresh', 'pr_d9_actions', 'while it''s still fresh', '아직 기억이 생생할 때', 'Short for "fresh in our minds". After a day, half the details are gone.', 'fresh in our minds를 줄인 말입니다. 하루만 지나도 자세한 내용의 절반은 잊힙니다.', 'meeting'),
  ('pr_d9_actions.ill_take_that_one', 'pr_d9_actions', 'I''ll take that one.', '그건 제가 맡을게요.', 'Claims a task in a meeting. Short and clear.', '회의에서 일을 맡겠다고 할 때 쓰는 짧고 분명한 말입니다.', 'meeting'),
  ('pr_d9_actions.rough_estimate', 'pr_d9_actions', 'A rough estimate is fine.', '대략적인 추정치면 돼요.', 'Rough = not exact. Also "a ballpark figure".', 'rough는 정확하지 않아도 된다는 뜻입니다. a ballpark figure라고도 합니다.', 'office'),
  ('pr_d9_actions.chasing_it', 'pr_d9_actions', 'Nobody''s chasing it.', '아무도 챙기고 있지 않아요.', '"Chase" = keep asking until a promised thing arrives.', 'chase는 약속한 것이 올 때까지 계속 챙겨 묻는다는 뜻입니다.', 'office'),
  ('pr_d9_actions.follow_up_with', 'pr_d9_actions', 'I''ll follow up with Dana.', '데이나에게 다시 확인할게요.', 'Follow up WITH a person, follow up ON a topic.', '사람에게는 follow up with, 주제에는 follow up on을 씁니다.', 'office'),
  ('pr_d9_actions.first_thing', 'pr_d9_actions', 'first thing tomorrow', '내일 아침 가장 먼저', 'Before any other work at the start of the day.', '하루를 시작하며 다른 일보다 먼저 한다는 뜻입니다.', 'office'),
  ('pr_d9_actions.owner_and_due_date', 'pr_d9_actions', 'an owner and a due date', '담당자와 기한', 'A task without both is only a wish.', '둘 중 하나라도 없는 할 일은 그저 바람일 뿐입니다.', 'meeting');

-- pr_d10_contract: Holding the line on the contract
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d10_contract', 1, 'greg',
   'A gray, chilly morning. The proposal is on the screen: $180,000 for phase one, payment Net 30.', '흐리고 쌀쌀한 아침입니다. 화면에 제안서가 떠 있습니다. 1단계 18만 달러, 지급 조건 Net 30.',
   'I''ve looked at the numbers. Honestly, one eighty is outside our budget. We were thinking closer to one fifty.', 'Hold the line: say you understand, and that the price reflects the work: forty stores, live data, and three months of support.', '물러서지 마세요. 이해한다고 하고, 가격에는 40개 매장, 실시간 데이터, 3개월 지원이라는 일의 크기가 반영되어 있다고 하세요.',
   '[{"any":["reflects","months of support","forty stores"]}]',
   'I understand. The price reflects the work: forty stores, live data, and three months of support.',
   '["I understand. The menu changes every week: soup, salad, and a sandwich.","I understand. The bus runs every day: mornings, evenings, and weekends.","I understand. The store is closed."]',
   '["Do not move the number. Explain what is inside it.","Key words: I understand, the price reflects the work, three months of support"]', '["숫자는 움직이지 말고, 그 안에 무엇이 들어 있는지 설명하세요.","핵심 단어: I understand, the price reflects the work, three months of support"]',
   'greg', 'That helps. But I still need the number to come down. Can you meet us halfway? Say, one sixty-five?', '도움이 되네요. 그래도 금액을 낮춰야 해요. 중간에서 만날 수 있을까요? 16만 5천 정도?'),
  ('pr_d10_contract', 2, 'greg',
   'You are not allowed to approve a discount on your own. Maya is.', '당신에게는 혼자서 할인을 승인할 권한이 없습니다. 마야에게는 있습니다.',
   'One sixty-five. Can we shake on that?', 'Say you are not in a position to agree to that today, and that you will need to run that by your manager.', '오늘은 거기에 동의할 수 있는 입장이 아니라고 하고, 매니저와 상의해야 한다고 하세요.',
   '[{"any":["not in a position","run that by","run it by"]}]',
   'I''m not in a position to agree to that today. I''ll need to run that by my manager.',
   '["I''m not in a hurry to get home today. I''ll need to stop at the market.","I''m not in the mood for pancakes today. I''ll have the omelet.","I''m not in the office on Friday."]',
   '["Neither yes nor no. Say who has to decide.","Key words: not in a position to, run that by my manager"]', '["예도 아니요도 아닙니다. 누가 결정해야 하는지 말하세요.","핵심 단어: not in a position to, run that by my manager"]',
   'greg', 'Fair enough. While you''re at it, payment terms. Our standard is Net 60.', '그러죠. 그 김에 지급 조건도 봅시다. 우리 기준은 Net 60이에요.'),
  ('pr_d10_contract', 3, 'greg',
   'Net 60 means waiting two months for every payment. You can give a little, if you get something back.', 'Net 60이면 돈을 받을 때마다 두 달을 기다려야 합니다. 조금 양보할 수는 있습니다. 받는 것이 있다면요.',
   'Net 30 is tough for our finance team.', 'Trade: say that if he can commit to a purchase order this week, you can do Net 45.', '맞바꾸세요. 이번 주 안에 발주서를 약속해 주면 Net 45로 할 수 있다고 하세요.',
   '[{"any":["45","forty five","purchase order"]}]',
   'If you can commit to a purchase order this week, we can do Net 45.',
   '["If you can come to the barbecue this week, we can make more potato salad.","If you can wait ten minutes, we can seat you by the window.","If you can carry the eggs, I can take the milk."]',
   '["Never give for free: \\"If you can …, we can …\\".","Key words: if you can commit to, a purchase order, we can do Net 45"]', '["그냥 내주지 마세요. \\"If you can …, we can …\\".","핵심 단어: if you can commit to, a purchase order, we can do Net 45"]',
   'greg', 'A PO this week for Net 45… I can live with that.', '이번 주 발주서에 Net 45라… 그 정도면 받아들일 수 있어요.');

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d10_contract', 4, 'greg',
   'Next is the service level agreement, the SLA.', '다음은 서비스 수준 협약(SLA)입니다.',
   'Last thing: uptime. We need a guarantee. What can you commit to?', 'Say you only promise what you can stand behind: 99.9 percent uptime and a four-hour response time for critical issues.', '책임질 수 있는 것만 약속한다고 하세요. 가동률 99.9퍼센트, 그리고 심각한 장애에는 4시간 안에 대응합니다.',
   '[{"all":["99"]},{"any":["stand behind","four hour","response time"]}]',
   'We only promise what we can stand behind: 99.9 percent uptime and a four-hour response time for critical issues.',
   '["We only serve what we can make fresh: soup, sandwiches and two kinds of pie.","We only take what we can carry: a backpack and a small suitcase.","We only open on weekdays."]',
   '["Give clear numbers for uptime and for how fast you answer.","Key words: stand behind, 99.9 percent uptime, four-hour response time"]', '["가동률과 대응 속도를 분명한 숫자로 말하세요.","핵심 단어: stand behind, 99.9 percent uptime, four-hour response time"]',
   'greg', 'That''s reasonable. Send me the revised terms and I''ll share them with legal.', '합리적이네요. 수정된 조건을 보내 주면 법무팀과 공유할게요.'),
  ('pr_d10_contract', 5, 'greg',
   'He comes back to the price one more time.', '그렉이 한 번 더 가격 이야기로 돌아옵니다.',
   'And the price? I need something to tell finance today.', 'Stay firm and friendly: for now one eighty stands, and you will have an answer for him by end of day.', '단호하되 상냥하게 말하세요. 지금은 18만이 그대로이고, 오늘 퇴근 전까지 답을 주겠다고요.',
   '[{"any":["stands","answer for you"]}]',
   'For now, one eighty stands. I''ll have an answer for you by end of day.',
   '["For now, the rain is staying. I''ll have an umbrella for you by lunchtime.","For now, the kitchen is closed. I''ll have a table for you at five.","For now, I''m just looking."]',
   '["A price that \\"stands\\" has not changed. Then say when he will hear from you.","Key words: for now, one eighty stands, an answer for you, by end of day"]', '["가격이 stands한다는 것은 바뀌지 않았다는 뜻입니다. 그리고 언제 답을 줄지 말하세요.","핵심 단어: for now, one eighty stands, an answer for you, by end of day"]',
   'greg', 'You drive a hard bargain, Priya. End of day, then.', '만만치 않게 협상하시네요, 프리야. 그럼 오늘 퇴근 전까지로 합시다.'),
  ('pr_d10_contract', 6, 'greg',
   'Almost noon. Derek and Jun have not said a word about money, just as you agreed.', '정오가 다 되어 갑니다. 약속한 대로 데릭과 준은 돈 이야기를 한마디도 하지 않았습니다.',
   'So where does that leave us?', 'Sum up where you landed: Net 45 with a PO this week, 99.9 percent uptime, and the price is still open.', '어디까지 합의했는지 정리하세요. 이번 주 발주서를 조건으로 Net 45, 가동률 99.9퍼센트, 그리고 가격은 아직 미정입니다.',
   '[{"any":["where we landed","still open","landed"]}]',
   'Here''s where we landed: Net 45 with a PO this week, 99.9 percent uptime, and the price is still open.',
   '["Here''s where we parked: level two, next to the elevator, and the ticket is in my pocket.","Here''s where we met: the bench by the fountain, on a sunny Saturday.","Here''s where I get off."]',
   '["List what is agreed, then say honestly what is not agreed yet.","Key words: here''s where we landed, Net 45, still open"]', '["합의된 것을 나열하고, 아직 합의되지 않은 것을 솔직히 말하세요.","핵심 단어: here''s where we landed, Net 45, still open"]',
   'greg', 'That matches my notes. Talk soon.', '제 메모와 같네요. 또 이야기합시다.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_d10_contract.price_reflects', 'pr_d10_contract', 'The price reflects the work.', '가격에는 일의 크기가 반영되어 있어요.', 'Defends a price by pointing at what the client gets for it.', '고객이 그 값으로 무엇을 받는지 짚어서 가격을 지키는 말입니다.', 'meeting'),
  ('pr_d10_contract.not_in_a_position', 'pr_d10_contract', 'I''m not in a position to agree to that.', '제가 거기에 동의할 수 있는 입장이 아니에요.', 'A polite way to say "I am not allowed to" or "I cannot".', '권한이 없거나 할 수 없다는 것을 공손하게 말하는 표현입니다.', 'meeting'),
  ('pr_d10_contract.run_that_by', 'pr_d10_contract', 'I''ll need to run that by my manager.', '매니저와 상의해 봐야 해요.', '"Run something by someone" = ask for their approval. It also buys you time.', 'run something by someone은 승인을 구한다는 뜻입니다. 시간을 버는 효과도 있습니다.', 'meeting'),
  ('pr_d10_contract.if_you_can_we_can', 'pr_d10_contract', 'If you can commit to a purchase order, we can do Net 45.', '발주서를 약속해 주시면 Net 45로 할 수 있어요.', 'The basic sentence of negotiating: every gift has a condition.', '협상의 기본 문장입니다. 내주는 것에는 늘 조건이 붙습니다.', 'meeting'),
  ('pr_d10_contract.purchase_order', 'pr_d10_contract', 'a purchase order (PO)', '발주서', 'The client''s official written order. With a PO, the work and the money are approved.', '고객이 내는 공식 주문서입니다. 발주서가 나오면 일과 예산이 승인된 것입니다.', 'office'),
  ('pr_d10_contract.stand_behind', 'pr_d10_contract', 'We only promise what we can stand behind.', '저희는 책임질 수 있는 것만 약속합니다.', '"Stand behind" a promise or a product = guarantee it.', '약속이나 제품을 stand behind한다는 것은 그것을 보증한다는 뜻입니다.', 'meeting'),
  ('pr_d10_contract.hard_bargain', 'pr_d10_contract', 'You drive a hard bargain.', '만만치 않게 협상하시네요.', 'Said, often with a smile, to someone who negotiates firmly.', '단단하게 협상하는 사람에게 흔히 웃으며 하는 말입니다.', 'meeting'),
  ('pr_d10_contract.where_we_landed', 'pr_d10_contract', 'Here''s where we landed.', '이렇게 정리됐습니다.', '"Land" = end up after a discussion. "Where did we land on the price?"', 'land는 논의 끝에 이른 결론을 뜻합니다. "Where did we land on the price?"처럼 묻습니다.', 'meeting');

-- pr_d10_signoff: Getting Maya's sign-off on the price
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d10_signoff', 1, 'maya',
   'Maya''s office. She has a jacket over her shoulders and the proposal on her screen.', '마야의 사무실입니다. 마야는 어깨에 재킷을 걸치고 화면에 제안서를 띄워 놓았습니다.',
   'Come on in. How''d the call with Greg go?', 'Bottom line first: give her the short version. He wants one sixty-five, and you held the line at one eighty.', '결론부터 말하세요. 요점만 말하면, 그렉은 16만 5천을 원하고 당신은 18만에서 물러서지 않았습니다.',
   '[{"any":["held the line","short version"]}]',
   'Short version: he wants one sixty-five, and I held the line at one eighty.',
   '["Long story short: he wants a window seat, and I booked the aisle.","Long story short: he wants pancakes, and I ordered the omelet.","Short story: I missed the bus."]',
   '["\\"Short version:\\" tells a busy manager the summary comes first.","Key words: short version, one sixty-five, held the line"]', '["\\"Short version:\\"은 바쁜 매니저에게 요약부터 말하겠다는 신호입니다.","핵심 단어: short version, one sixty-five, held the line"]',
   'maya', 'Good. That''s about eight percent off. What do you recommend?', '잘했어요. 8퍼센트쯤 깎아 달라는 거네요. 어떻게 하면 좋겠어요?'),
  ('pr_d10_signoff', 2, 'maya',
   'You thought about this over lunch.', '점심을 먹으면서 생각해 둔 것이 있습니다.',
   'I want your recommendation, not just the problem.', 'Recommend five percent off, but only if they sign a one-year support contract.', '5퍼센트 할인을 제안하되, 1년 지원 계약을 맺는 경우에만이라고 하세요.',
   '[{"all":["support"],"any":["five percent","5 percent","one year","only if"]}]',
   'My recommendation is five percent off, but only if they sign a one-year support contract.',
   '["My recommendation is the chicken noodle soup, but only if you like noodles.","My recommendation is the early bus, but only if you can get up at six.","My recommendation is the apple pie."]',
   '["\\"My recommendation is …\\" plus the condition: \\"but only if …\\".","Key words: my recommendation is, five percent off, only if, one-year support contract"]', '["\\"My recommendation is …\\"에 \\"but only if …\\"로 조건을 붙이세요.","핵심 단어: my recommendation is, five percent off, only if, one-year support contract"]',
   'maya', 'So we give a little now and get a year of steady revenue. I like it.', '지금 조금 내주고 1년 동안 안정된 매출을 얻는 거네요. 마음에 들어요.'),
  ('pr_d10_signoff', 3, 'maya',
   'Maya likes to test an idea before she approves it.', '마야는 승인하기 전에 생각을 시험해 보기를 좋아합니다.',
   'Let me push on that. Why not just give him the eight percent and close today?', 'Say it would set a precedent: he would expect a discount on every phase after this.', '선례가 된다고 하세요. 앞으로 단계마다 할인을 기대하게 될 거라고요.',
   '[{"any":["precedent","every phase"]}]',
   'Because it would set a precedent. He''d expect a discount on every phase after this.',
   '["Because it would set off the alarm. He''d wake up every neighbor on the street.","Because it would melt in the car. He''d have to eat it on the way.","Because it would rain."]',
   '["A \\"precedent\\" is something done once that people expect again.","Key words: set a precedent, a discount on every phase"]', '["precedent는 한 번 하면 다음에도 기대하게 되는 선례입니다.","핵심 단어: set a precedent, a discount on every phase"]',
   'maya', 'Exactly what I wanted to hear. Five percent is my limit, though.', '바로 그 말을 듣고 싶었어요. 그래도 5퍼센트가 한계예요.'),
  ('pr_d10_signoff', 4, 'maya',
   'There is one thing you agreed to on the call without asking her.', '통화에서 마야에게 묻지 않고 합의한 것이 하나 있습니다.',
   'Anything else I should know before I sign off?', 'Tell her you agreed to Net 45 in exchange for a purchase order this week, and ask if she is comfortable with that.', '이번 주 발주서를 받는 조건으로 Net 45에 합의했다고 알리고, 그래도 괜찮은지 물어보세요.',
   '[{"any":["comfortable","net 45","purchase order"]}]',
   'One more thing: I agreed to Net 45 in exchange for a purchase order this week. Are you comfortable with that?',
   '["One more thing: I asked for wheat toast in place of the home fries. Are you ready to order?","One more thing: I left my umbrella in your car. Are you driving tomorrow?","One more thing: the milk is on sale."]',
   '["Tell her what you already gave away, then check: \\"Are you comfortable with that?\\"","Key words: I agreed to Net 45, in exchange for, are you comfortable with that"]', '["이미 내준 것을 알리고 확인하세요. \\"Are you comfortable with that?\\"","핵심 단어: I agreed to Net 45, in exchange for, are you comfortable with that"]',
   'maya', 'Very. A PO this week is worth more than fifteen days. Just don''t put the discount in writing until legal reviews it.', '그럼요. 이번 주 발주서가 15일보다 값져요. 다만 법무팀이 검토하기 전에는 할인을 서면으로 남기지 마세요.'),
  ('pr_d10_signoff', 5, 'maya',
   'Maya picks up her pen.', '마야가 펜을 집어 듭니다.',
   'So, are we clear on the limits?', 'Confirm: five percent is the ceiling, nothing goes out until legal signs off, and you will brief Jun before he flies.', '확인하세요. 5퍼센트가 상한선이고, 법무팀이 승인하기 전에는 아무것도 내보내지 않으며, 준이 떠나기 전에 내용을 알려 주겠다고요.',
   '[{"any":["ceiling","brief jun","legal signs off"]}]',
   'Clear. Five percent is the ceiling, nothing goes out until legal signs off, and I''ll brief Jun before he flies.',
   '["Clear. Two eggs is the usual, nothing goes on the toast, and I''ll pay at the counter.","Clear. Six o''clock is the last bus, and I''ll walk if I miss it.","Clear skies all weekend."]',
   '["Repeat the limit and the condition, and add who you will tell.","Key words: five percent is the ceiling, legal signs off, brief Jun"]', '["한도와 조건을 되짚고, 누구에게 알릴지 덧붙이세요.","핵심 단어: five percent is the ceiling, legal signs off, brief Jun"]',
   'maya', 'Perfect. You have my sign-off. Let me know if you have any questions.', '완벽해요. 승인할게요. 궁금한 게 있으면 말해 줘요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_d10_signoff.short_version', 'pr_d10_signoff', 'Short version: he wants one sixty-five.', '요점만 말하면, 그는 16만 5천을 원해요.', 'Announces a summary. The long version follows only if the listener asks.', '요약을 알리는 말입니다. 자세한 이야기는 상대가 물을 때만 합니다.', 'meeting'),
  ('pr_d10_signoff.held_the_line', 'pr_d10_signoff', 'I held the line at one eighty.', '18만에서 물러서지 않았어요.', '"Hold the line" = refuse to move from your position.', 'hold the line은 자기 입장에서 물러서지 않는다는 뜻입니다.', 'meeting'),
  ('pr_d10_signoff.my_recommendation', 'pr_d10_signoff', 'My recommendation is five percent off.', '제 의견은 5퍼센트 할인입니다.', 'Bring your manager a recommendation, not only a problem.', '매니저에게는 문제만이 아니라 해결 의견도 함께 가져가세요.', 'meeting'),
  ('pr_d10_signoff.only_if', 'pr_d10_signoff', '…, but only if they sign a one-year support contract.', '…, 단 1년 지원 계약을 맺는 경우에만요.', '"Only if" makes the condition strict: no contract, no discount.', 'only if는 조건을 엄격하게 만듭니다. 계약이 없으면 할인도 없습니다.', 'meeting'),
  ('pr_d10_signoff.let_me_push', 'pr_d10_signoff', 'Let me push on that.', '그 부분을 좀 더 따져 볼게요.', 'A manager testing your idea. It is a good sign, not an attack.', '매니저가 당신의 생각을 시험해 보는 말입니다. 공격이 아니라 좋은 신호입니다.', 'meeting'),
  ('pr_d10_signoff.set_a_precedent', 'pr_d10_signoff', 'It would set a precedent.', '선례가 될 거예요.', 'What you do once, people will expect next time.', '한 번 해 주면 다음에도 기대하게 된다는 뜻입니다.', 'meeting'),
  ('pr_d10_signoff.comfortable_with', 'pr_d10_signoff', 'Are you comfortable with that?', '그렇게 해도 괜찮으시겠어요?', 'Asks if someone accepts a decision. Softer than "Do you agree?"', '결정을 받아들이는지 묻는 말입니다. "Do you agree?"보다 부드럽습니다.', 'meeting'),
  ('pr_d10_signoff.ceiling', 'pr_d10_signoff', 'Five percent is the ceiling.', '5퍼센트가 상한선이에요.', 'Ceiling = the highest you may go. The lowest is "the floor".', 'ceiling은 올라갈 수 있는 가장 높은 선이고, 가장 낮은 선은 the floor입니다.', 'meeting');

-- pr_d10_refund: Did the gift card fix ship?
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d10_refund', 1, 'derek',
   'A chilly afternoon. Derek has his hood up and a fresh mug of coffee.', '쌀쌀한 오후입니다. 데릭은 후드를 뒤집어쓰고 갓 내린 커피를 들고 있습니다.',
   'Uh-oh. You''ve got that "is it done yet" look.', 'Admit it, and ask where you stand on the gift card refund fix.', '그렇다고 인정하고, 기프트 카드 환불 수정이 어디까지 됐는지 물어보세요.',
   '[{"any":["where do we stand","stand on","where are we"]}]',
   'Guilty. Where do we stand on the gift card refund fix?',
   '["Guilty. Where do we keep the coffee filters?","Hungry. Where do we order the good pizza?","Lost. Where do we catch the 12 bus?"]',
   '["\\"Where do we stand on …?\\" asks for the current status.","Key words: where do we stand on, the gift card refund fix"]', '["\\"Where do we stand on …?\\"은 지금 상태가 어떤지 묻는 말입니다.","핵심 단어: where do we stand on, the gift card refund fix"]',
   'derek', 'It went out at noon. It''s live in production.', '정오에 나갔어요. 운영 환경에 올라가 있어요.'),
  ('pr_d10_refund', 2, 'derek',
   'On time. But "live" and "working" are not the same thing.', '제때 나갔습니다. 하지만 올라간 것과 잘 돌아가는 것은 다릅니다.',
   'Jun wrote the tests, and I did the release.', 'Say that is great news, and ask if anyone has tested it with a real gift card since the release.', '정말 좋은 소식이라고 하고, 배포한 뒤에 실제 기프트 카드로 시험해 본 사람이 있는지 물어보세요.',
   '[{"any":["tested","real gift card","since the release"]}]',
   'That''s great news. Has anyone tested it with a real gift card since the release?',
   '["That''s great news. Has anyone seen my blue umbrella since the meeting?","That''s great news. Has anyone fed the cat since breakfast?","That''s great news. Has anyone called a cab?"]',
   '["Praise first, then check: \\"Has anyone …?\\"","Key words: great news, has anyone tested it, a real gift card, since the release"]', '["먼저 칭찬하고, \\"Has anyone …?\\"으로 확인하세요.","핵심 단어: great news, has anyone tested it, a real gift card, since the release"]',
   'derek', 'Jun ran three refunds an hour ago. All three went through. There''s one catch, though.', '준이 한 시간 전에 환불을 세 건 해 봤어요. 세 건 다 처리됐고요. 그런데 걸리는 게 하나 있어요.'),
  ('pr_d10_refund', 3, 'derek',
   'There is always a catch.', '걸리는 점은 늘 있기 마련입니다.',
   'Gift cards from before last March still fail. It''s maybe one refund in a hundred.', 'Ask if there is a workaround for those in the meantime.', '그동안 그런 경우에 쓸 수 있는 우회 방법이 있는지 물어보세요.',
   '[{"any":["workaround","in the meantime","work around"]}]',
   'Is there a workaround for those in the meantime?',
   '["Is there a bakery around here that opens early?","Is there a later bus for those of us who missed this one?","Is there a restroom on this floor?"]',
   '["A \\"workaround\\" gets the job done another way until the real fix is ready.","Key words: a workaround, in the meantime"]', '["workaround는 제대로 된 수정이 나올 때까지 다른 길로 일을 해내는 방법입니다.","핵심 단어: a workaround, in the meantime"]',
   'derek', 'Support can refund them by hand. I''ll have a real fix next sprint.', '지원팀이 손으로 환불해 줄 수 있어요. 제대로 된 수정은 다음 스프린트에 할게요.'),
  ('pr_d10_refund', 4, 'derek',
   'One in a hundred. Greg might never notice. Or he might.', '백 건에 한 건. 그렉은 끝내 모를 수도 있습니다. 알게 될 수도 있고요.',
   'Do you want to tell Greg now, or wait until it''s perfect?', 'Say you will tell him today, known issue and all, because you do not want any surprises.', '알려진 문제까지 포함해서 오늘 다 말하겠다고 하세요. 나중에 놀랄 일을 만들고 싶지 않다고요.',
   '[{"any":["known issue","surprises","tell him today"]}]',
   'I''ll tell him today, known issue and all. I don''t want any surprises.',
   '["I''ll tell him on Sunday, birthday cake and all. I don''t want any presents.","I''ll take it to go, fries and all. I don''t want any ketchup.","I''ll think about it."]',
   '["\\"… and all\\" = including the part that is not so nice.","Key words: tell him today, known issue and all, no surprises"]', '["\\"… and all\\"은 좋지 않은 부분까지 포함한다는 뜻입니다.","핵심 단어: tell him today, known issue and all, no surprises"]',
   'derek', 'And that''s why he trusts you.', '그래서 그렉이 프리야를 믿는 거예요.'),
  ('pr_d10_refund', 5, 'derek',
   'You open a new email to Greg.', '그렉에게 보낼 새 이메일을 엽니다.',
   'Anything you need from me for that email?', 'Ask for two lines for the release notes, and thank him for getting this over the finish line.', '릴리스 노트에 넣을 두 줄을 부탁하고, 끝까지 마무리해 줘서 고맙다고 하세요.',
   '[{"any":["release notes","finish line"]}]',
   'Just two lines for the release notes. And thanks for getting this over the finish line.',
   '["Just two eggs for the omelet. And thanks for holding the door.","Just two blocks to the park. And thanks for the ride.","Just two sugars, thanks."]',
   '["Ask for something small and exact, then thank him for finishing.","Key words: two lines for the release notes, over the finish line"]', '["작고 구체적인 것을 부탁한 뒤, 마무리해 준 것에 고마움을 전하세요.","핵심 단어: two lines for the release notes, over the finish line"]',
   'derek', 'No rush, right? Just kidding. You''ll have them in ten minutes.', '급한 건 아니죠? 농담이에요. 10분 안에 보낼게요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_d10_refund.where_do_we_stand', 'pr_d10_refund', 'Where do we stand on the gift card fix?', '기프트 카드 수정은 어디까지 됐어요?', 'Asks for the status of one topic. Answer with done, not done, or a date.', '한 가지 일의 상태를 묻는 말입니다. 끝났는지, 아닌지, 언제 되는지로 답합니다.', 'office'),
  ('pr_d10_refund.live_in_production', 'pr_d10_refund', 'It''s live in production.', '운영 환경에 올라가 있어요.', 'Production = the real system that customers use. "Live" = turned on.', 'production은 고객이 실제로 쓰는 시스템이고, live는 켜져 있다는 뜻입니다.', 'office'),
  ('pr_d10_refund.went_through', 'pr_d10_refund', 'All three went through.', '세 건 다 처리됐어요.', 'A payment, refund or order "goes through" when it is completed.', '결제, 환불, 주문이 완료되면 go through했다고 합니다.', 'office'),
  ('pr_d10_refund.one_catch', 'pr_d10_refund', 'There''s one catch, though.', '그런데 걸리는 게 하나 있어요.', 'A catch = a hidden problem in something that sounds good.', 'catch는 좋아 보이는 일에 숨어 있는 문제를 말합니다.', 'office'),
  ('pr_d10_refund.workaround', 'pr_d10_refund', 'Is there a workaround?', '우회할 방법이 있어요?', 'A temporary way around a problem. Not a fix.', '문제를 잠시 피해 가는 방법입니다. 수정은 아닙니다.', 'office'),
  ('pr_d10_refund.in_the_meantime', 'pr_d10_refund', 'in the meantime', '그동안에는', 'During the time before something else happens.', '다른 일이 일어나기 전까지의 시간을 가리킵니다.', 'office'),
  ('pr_d10_refund.known_issue_and_all', 'pr_d10_refund', 'I''ll tell him today, known issue and all.', '알려진 문제까지 포함해서 오늘 말할게요.', 'A "known issue" is a problem you have found and written down but not fixed yet.', 'known issue는 찾아내서 기록해 두었지만 아직 고치지 않은 문제입니다.', 'office'),
  ('pr_d10_refund.finish_line', 'pr_d10_refund', 'Thanks for getting this over the finish line.', '끝까지 마무리해 줘서 고마워요.', 'From racing. Thanks people for the hard last part of a job.', '경주에서 온 말입니다. 일의 힘든 마지막 구간을 해낸 사람에게 고마움을 전합니다.', 'office');

-- pr_d11_clause: A last-minute clause
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d11_clause', 1, 'greg',
   'A clear Thursday morning. Jun is in the air. The phone in the meeting room rings.', '맑은 목요일 아침입니다. 준은 비행기 안에 있습니다. 회의실 전화가 울립니다.',
   'Priya, it''s Greg. Sorry to spring this on you, but legal wants to add a clause before Jun gets here.', 'Stay calm. Thank him for telling you before the meeting, and ask what exactly the clause says.', '침착하세요. 회의 전에 알려 줘서 고맙다고 하고, 그 조항이 정확히 어떤 내용인지 물어보세요.',
   '[{"any":["what exactly","clause say","clause says"]}]',
   'Thanks for telling me before the meeting. What exactly does the clause say?',
   '["Thanks for telling me before the movie. How much does the ticket cost?","Thanks for saving me a seat. What time does the game start?","Thanks for the muffin."]',
   '["First the facts. Ask \\"What exactly …?\\" before you react.","Key words: thanks for telling me, what exactly, the clause"]', '["먼저 사실부터 확인하세요. 반응하기 전에 \\"What exactly …?\\"로 물어보세요.","핵심 단어: thanks for telling me, what exactly, the clause"]',
   'greg', 'A late-delivery penalty. Two percent of the contract for every week past November first.', '납기 지연 위약금이에요. 11월 1일을 넘기면 한 주마다 계약 금액의 2퍼센트.'),
  ('pr_d11_clause', 2, 'greg',
   'Two percent of $171,000 is more than $3,400 a week. You write the number down.', '17만 1천 달러의 2퍼센트면 한 주에 3,400달러가 넘습니다. 당신은 그 숫자를 적어 둡니다.',
   'Legal says it''s standard. Can I tell them you''re fine with it?', 'Check that you have it right: two percent a week, with no cap?', '제대로 이해했는지 확인하세요. 한 주에 2퍼센트이고, 상한은 없는 건가요?',
   '[{"any":["have this right","no cap","got this right"]}]',
   'Let me make sure I have this right: two percent a week, with no cap?',
   '["Let me make sure I have my keys: two for the door, one for the mailbox.","Let me make you a sandwich: turkey and cheese, with no mayo.","Let me get the door."]',
   '["Repeat the terms as a question. A \\"cap\\" is an upper limit.","Key words: make sure I have this right, two percent a week, no cap"]', '["조건을 질문으로 되짚으세요. cap은 상한선입니다.","핵심 단어: make sure I have this right, two percent a week, no cap"]',
   'greg', 'No cap. I know how that sounds.', '상한은 없어요. 어떻게 들릴지 저도 압니다.'),
  ('pr_d11_clause', 3, 'greg',
   'He wants an answer now. You do not have to give one.', '그렉은 지금 답을 원합니다. 하지만 지금 답할 필요는 없습니다.',
   'I need an answer before Jun walks in at two. Yes or no?', 'Say you cannot agree to that on the spot. Ask for an hour, and promise to call him back with an answer.', '이 자리에서 바로 동의할 수는 없다고 하세요. 한 시간만 달라고 하고, 답을 가지고 다시 전화하겠다고 약속하세요.',
   '[{"any":["on the spot","give me an hour","call you back"]}]',
   'I can''t agree to that on the spot. Give me an hour, and I''ll call you back with an answer.',
   '["I can''t eat all that by myself. Give me a box, and I''ll take the rest home.","I can''t see the screen from here. Give me a second, and I''ll move my chair.","I can''t find my badge."]',
   '["Buy time with a clear limit: how long, and what he gets then.","Key words: can''t agree on the spot, give me an hour, call you back"]', '["분명한 기한을 두고 시간을 버세요. 얼마 동안인지, 그때 무엇을 받게 되는지 말합니다.","핵심 단어: can''t agree on the spot, give me an hour, call you back"]',
   'greg', 'An hour. Fine. But I''m telling you, the board won''t sign without something.', '한 시간. 좋아요. 그래도 말해 두는데, 이사회는 뭐라도 없으면 서명하지 않을 겁니다.');

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d11_clause', 4, 'greg',
   '"Without something." So the penalty itself may not be the point.', '"뭐라도 없으면." 그렇다면 위약금 자체가 핵심은 아닐지도 모릅니다.',
   'They were very clear about that.', 'Ask him to help you understand: what is the concern behind the clause?', '이해할 수 있게 도와 달라고 하세요. 그 조항 뒤에 있는 걱정이 무엇인지 물어보세요.',
   '[{"any":["help me understand","concern behind","what is the concern"]}]',
   'Help me understand. What''s the concern behind the clause?',
   '["Help me carry this. What''s the code for the front door?","Help me choose. What''s the difference between the soup and the chili?","Help yourself."]',
   '["Ask about the worry, not about the wording.","Key words: help me understand, the concern behind the clause"]', '["문구가 아니라 걱정이 무엇인지 물어보세요.","핵심 단어: help me understand, the concern behind the clause"]',
   'greg', 'They got burned by a vendor last year. Six months late, and nobody said a word until the last week.', '작년에 어떤 업체한테 크게 데었어요. 6개월이나 늦었는데, 마지막 주까지 아무도 말을 안 해 줬죠.'),
  ('pr_d11_clause', 5, 'greg',
   'So it is about surprises, not about money.', '그렇다면 문제는 돈이 아니라 뒤늦게 알게 되는 일입니다.',
   'They don''t want to be surprised again.', 'Offer something better: a weekly status report, and written notice as soon as any date is at risk, in place of a penalty.', '더 나은 안을 내놓으세요. 위약금 대신 주간 현황 보고를 하고, 날짜가 위험해지면 바로 서면으로 알리겠다고요.',
   '[{"any":["status report","written notice","weekly"]}]',
   'What if we offered a weekly status report, and written notice as soon as any date is at risk, in place of a penalty?',
   '["What if we ordered a large pizza, and a salad as soon as everybody gets here?","What if we took the early bus, and had breakfast downtown?","What if it rains?"]',
   '["Solve the worry another way: \\"What if we offered …?\\"","Key words: what if we offered, a weekly status report, written notice, in place of a penalty"]', '["걱정을 다른 방법으로 풀어 주세요. \\"What if we offered …?\\"","핵심 단어: what if we offered, a weekly status report, written notice, in place of a penalty"]',
   'greg', 'No surprises in place of penalties… I could take that to legal. Can you put it in an email?', '위약금 대신 놀랄 일을 없앤다… 그거라면 법무팀에 가져가 볼 수 있겠어요. 이메일로 보내 줄 수 있어요?'),
  ('pr_d11_clause', 6, 'greg',
   'Maya said it yesterday: nothing in writing until she and legal have seen it.', '어제 마야가 말했습니다. 마야와 법무팀이 보기 전에는 아무것도 서면으로 남기지 말라고요.',
   'Five lines would do.', 'Say you will loop in Maya first, and that he will have it in writing as soon as she signs off.', '먼저 마야에게 알리겠다고 하고, 마야가 승인하는 대로 서면으로 보내겠다고 하세요.',
   '[{"any":["loop in maya","loop maya in","signs off"]}]',
   'Let me loop in Maya first. You''ll have it in writing as soon as she signs off.',
   '["Let me lock up the office first. You''ll have the keys as soon as I''m done.","Let me look at the menu first. You''ll have my order in a minute.","Let me sleep on it."]',
   '["Say who has to see it first, and when he will get it.","Key words: loop in Maya first, in writing, as soon as she signs off"]', '["누가 먼저 봐야 하는지, 그리고 그렉이 언제 받게 되는지 말하세요.","핵심 단어: loop in Maya first, in writing, as soon as she signs off"]',
   'greg', 'Fair enough. And Priya? Thanks for not just saying no.', '그러죠. 그리고 프리야, 그냥 안 된다고만 하지 않아서 고마워요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_d11_clause.spring_this_on_you', 'pr_d11_clause', 'Sorry to spring this on you.', '갑자기 이런 얘기를 꺼내서 미안해요.', '"Spring something on someone" = surprise them with it at the last minute.', 'spring something on someone은 막판에 갑자기 꺼내 놀라게 한다는 뜻입니다.', 'office'),
  ('pr_d11_clause.have_this_right', 'pr_d11_clause', 'Let me make sure I have this right.', '제가 제대로 이해했는지 확인할게요.', 'Slows the talk down and shows you are listening, not fighting.', '대화의 속도를 늦추고, 맞서는 것이 아니라 듣고 있음을 보여 줍니다.', 'meeting'),
  ('pr_d11_clause.no_cap', 'pr_d11_clause', 'two percent a week, with no cap', '상한 없이 한 주에 2퍼센트', 'A cap is an upper limit on an amount. "Capped at ten percent" = never more than ten.', 'cap은 금액의 상한선입니다. capped at ten percent는 10퍼센트를 넘지 않는다는 뜻입니다.', 'office'),
  ('pr_d11_clause.on_the_spot', 'pr_d11_clause', 'I can''t agree to that on the spot.', '이 자리에서 바로 동의할 수는 없어요.', '"On the spot" = right now, without time to think.', 'on the spot은 생각할 시간 없이 지금 당장이라는 뜻입니다.', 'meeting'),
  ('pr_d11_clause.give_me_an_hour', 'pr_d11_clause', 'Give me an hour, and I''ll call you back with an answer.', '한 시간만 주세요. 답을 가지고 다시 전화할게요.', 'Buying time works when you name the time and keep it.', '시간을 벌려면 기한을 말하고 그 기한을 지켜야 합니다.', 'office'),
  ('pr_d11_clause.help_me_understand', 'pr_d11_clause', 'Help me understand.', '제가 이해할 수 있게 설명해 주세요.', 'Asks for the reason without sounding like an attack. Softer than "Why?"', '따지는 느낌 없이 이유를 묻는 말입니다. "Why?"보다 부드럽습니다.', 'meeting'),
  ('pr_d11_clause.got_burned', 'pr_d11_clause', 'They got burned by a vendor last year.', '작년에 어떤 업체한테 크게 데었어요.', '"Get burned" = be hurt by trusting someone. A vendor is a company that sells you a service.', 'get burned는 믿었다가 손해를 본다는 뜻입니다. vendor는 서비스를 파는 업체입니다.', 'office'),
  ('pr_d11_clause.take_that_to_legal', 'pr_d11_clause', 'I could take that to legal.', '그거라면 법무팀에 가져가 볼 수 있겠어요.', '"Legal" = the legal department. "Take it to" = present it for approval.', 'legal은 법무팀입니다. take it to는 승인을 받으러 가져간다는 뜻입니다.', 'office');

-- pr_d11_jun: Coaching Jun before the client visit
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d11_jun', 1, 'jun',
   'Your phone buzzes on your desk. It is Jun, calling from the Pinecrest Hotel in Ridgeport.', '책상 위에서 휴대전화가 울립니다. 리지포트의 파인크레스트 호텔에서 준이 건 전화입니다.',
   'Hi, Priya. I just checked in. The meeting with Greg is at two, and honestly, I''m a little nervous.', 'Tell him that is completely normal, and that he knows this project better than anyone in that room.', '그건 아주 당연한 일이라고 하고, 그 회의실의 누구보다 준이 이 프로젝트를 잘 안다고 말해 주세요.',
   '[{"any":["normal","better than anyone"]}]',
   'That''s completely normal. You know this project better than anyone in that room.',
   '["That''s completely free. You get a cookie with any coffee in that shop.","That''s completely sold out. You have to wait for the next show.","That''s completely wrong."]',
   '["First the feeling, then a fact that gives him confidence.","Key words: completely normal, better than anyone, in that room"]', '["먼저 마음을 받아 주고, 자신감을 줄 사실을 말하세요.","핵심 단어: completely normal, better than anyone, in that room"]',
   'jun', 'Thanks. I needed that.', '고마워요. 그 말이 필요했어요.'),
  ('pr_d11_jun', 2, 'jun',
   'You hear him turn a page in his notebook.', '준이 공책을 넘기는 소리가 들립니다.',
   'So what should I focus on?', 'Tell him to stick to what you agreed on: Net 45, five percent with the support contract, and 99.9 percent uptime.', '합의한 내용에서 벗어나지 말라고 하세요. Net 45, 지원 계약을 조건으로 5퍼센트, 가동률 99.9퍼센트입니다.',
   '[{"any":["stick to","agreed on","what we agreed"]}]',
   'Stick to what we agreed on: Net 45, five percent with the support contract, and 99.9 percent uptime.',
   '["Stay in the right lane: Lake Avenue, then Cedar Street, and the parking lot.","Stick a stamp on it: the post office closes at five.","Stick around for dessert."]',
   '["\\"Stick to\\" = do not move away from. Then list the three terms.","Key words: stick to what we agreed on, Net 45, five percent, 99.9 percent"]', '["stick to는 거기서 벗어나지 않는다는 뜻입니다. 그리고 조건 세 가지를 말하세요.","핵심 단어: stick to what we agreed on, Net 45, five percent, 99.9 percent"]',
   'jun', 'Net 45, five percent, 99.9. They''re on the first page of my notes.', 'Net 45, 5퍼센트, 99.9. 메모 첫 장에 적어 뒀어요.'),
  ('pr_d11_jun', 3, 'jun',
   'Greg likes to ask for one more thing at the end of a meeting.', '그렉은 회의가 끝날 때쯤 하나만 더 하며 부탁하기를 좋아합니다.',
   'What if he asks for something new? A bigger discount, or another feature?', 'Tell him not to promise anything in the room. He should say, "Let me take that back to the team."', '그 자리에서는 아무것도 약속하지 말라고 하세요. "Let me take that back to the team."이라고 말하면 된다고요.',
   '[{"any":["take that back","take it back","in the room"]}]',
   'Don''t promise anything in the room. Just say, "Let me take that back to the team."',
   '["Don''t leave anything in the car. Just say, \\"Let me take that bag to the lobby.\\"","Don''t order anything spicy. Just say, \\"I''ll have what she''s having.\\"","Don''t be late."]',
   '["Give him one sentence he can use when he feels pushed.","Key words: don''t promise anything in the room, take that back to the team"]', '["밀린다고 느낄 때 쓸 수 있는 문장 하나를 알려 주세요.","핵심 단어: don''t promise anything in the room, take that back to the team"]',
   'jun', '"Let me take that back to the team." Okay. That buys me time.', '"Let me take that back to the team." 알겠어요. 그러면 시간을 벌 수 있겠네요.'),
  ('pr_d11_jun', 4, 'jun',
   'You read the contract draft last night. One line jumped out at you.', '어젯밤에 계약서 초안을 읽었습니다. 한 줄이 눈에 걸렸습니다.',
   'Is there anything I should watch out for in the draft?', 'Tell him to push back on the seven-day cancellation notice: you need thirty days.', '7일 전 해지 통보 조항에는 이의를 제기하라고 하세요. 30일이 필요합니다.',
   '[{"any":["push back","thirty","30"]}]',
   'Yes. Push back on the seven-day cancellation notice. We need thirty days.',
   '["Yes. Push the door on the left side. We need more light in here.","Yes. Put back the milk on the top shelf. We need eggs.","Yes. Watch out for the wet floor."]',
   '["\\"Push back on\\" = disagree with politely. Name the clause and the number you need.","Key words: push back on, seven-day cancellation notice, thirty days"]', '["push back on은 정중하게 이의를 제기한다는 뜻입니다. 조항과 필요한 숫자를 말하세요.","핵심 단어: push back on, seven-day cancellation notice, thirty days"]',
   'jun', 'Seven days is too short. Ask for thirty. Got it.', '7일은 너무 짧다. 30일을 요청한다. 알겠습니다.'),
  ('pr_d11_jun', 5, 'jun',
   'It is almost one thirty. Jun has to leave for Summit Retail soon.', '한 시 반이 다 되어 갑니다. 준은 곧 서밋 리테일로 출발해야 합니다.',
   'And what if I get stuck?', 'Tell him to step out and call you: you are only a phone call away. And tell him he has got this.', '잠깐 나와서 전화하라고 하세요. 전화 한 통이면 닿는 곳에 있다고요. 그리고 잘 해낼 거라고 말해 주세요.',
   '[{"any":["phone call away","step out","you have got this"]}]',
   'Then step out and call me. I''m only a phone call away. You''ve got this.',
   '["Then sit down and eat something. I''m only having a salad.","Then turn around and go home. I''m not waiting in this rain.","Then try again tomorrow."]',
   '["Tell him what to do, where you are, and that you believe in him.","Key words: step out and call me, a phone call away, you''ve got this"]', '["어떻게 하면 되는지, 당신이 어디에 있는지, 그리고 그를 믿는다는 것을 말하세요.","핵심 단어: step out and call me, a phone call away, you''ve got this"]',
   'jun', 'Thanks, Priya. I''ll text you when it''s over.', '고마워요, 프리야. 끝나면 문자 드릴게요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_d11_jun.completely_normal', 'pr_d11_jun', 'That''s completely normal.', '그건 아주 당연한 거예요.', 'Calms someone by telling them everybody feels the same way.', '누구나 그렇게 느낀다고 말해 주어 마음을 가라앉히는 말입니다.', 'office'),
  ('pr_d11_jun.better_than_anyone', 'pr_d11_jun', 'You know this project better than anyone in that room.', '그 회의실의 누구보다 당신이 이 프로젝트를 잘 알아요.', 'Confidence comes from a fact, not from "Don''t worry."', '자신감은 걱정 말라는 말이 아니라 사실에서 나옵니다.', 'office'),
  ('pr_d11_jun.stick_to_agreed', 'pr_d11_jun', 'Stick to what we agreed on.', '합의한 내용에서 벗어나지 마세요.', '"Stick to" a plan, a budget, the facts = stay with it.', '계획, 예산, 사실에 stick to한다는 것은 거기서 벗어나지 않는다는 뜻입니다.', 'meeting'),
  ('pr_d11_jun.in_the_room', 'pr_d11_jun', 'Don''t promise anything in the room.', '그 자리에서는 아무것도 약속하지 마세요.', '"In the room" = during the meeting, face to face, where the pressure is.', 'in the room은 얼굴을 맞대고 압박을 받는 회의 자리를 말합니다.', 'meeting'),
  ('pr_d11_jun.take_that_back', 'pr_d11_jun', 'Let me take that back to the team.', '그건 팀에 가져가서 상의해 볼게요.', 'A safe answer to any new request. It is neither yes nor no.', '새로운 요청에는 언제나 안전한 답입니다. 예도 아니요도 아닙니다.', 'meeting'),
  ('pr_d11_jun.buys_me_time', 'pr_d11_jun', 'That buys me time.', '그러면 시간을 벌 수 있겠네요.', '"Buy time" = get more time before you must decide.', 'buy time은 결정하기 전에 시간을 더 얻는다는 뜻입니다.', 'office'),
  ('pr_d11_jun.watch_out_for', 'pr_d11_jun', 'Is there anything I should watch out for?', '조심해야 할 게 있을까요?', '"Watch out for" = be careful about. A good question before any meeting.', 'watch out for는 조심한다는 뜻입니다. 어떤 회의 전에든 좋은 질문입니다.', 'office'),
  ('pr_d11_jun.phone_call_away', 'pr_d11_jun', 'I''m only a phone call away.', '전화 한 통이면 닿아요.', 'Tells someone that help is near. Then: "You''ve got this" = you can do it.', '도움이 가까이 있다는 말입니다. 이어지는 "You''ve got this"는 당신은 할 수 있다는 뜻입니다.', 'office');

-- pr_d12_signed: It's official: the contract is signed
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d12_signed', 1, 'jun',
   'Friday morning, partly sunny. Maya signed from her office a few minutes ago. Your phone rings.', '구름 사이로 해가 나는 금요일 아침입니다. 몇 분 전에 마야가 사무실에서 서명했습니다. 휴대전화가 울립니다.',
   'Priya! It''s signed. Greg signed right after Maya. It''s official!', 'Congratulate him and tell him he pulled it off.', '축하하고, 준이 해냈다고 말해 주세요.',
   '[{"any":["congratulations","congrats","pulled it off"]}]',
   'That''s fantastic news! Congratulations, Jun. You pulled it off.',
   '["That''s fantastic pie! My compliments, Rosa. You baked it yourself?","That''s a fantastic price! Thanks, Mike. You saved me ten dollars.","That''s my bus!"]',
   '["\\"Pull it off\\" = succeed at something difficult.","Key words: fantastic news, congratulations, you pulled it off"]', '["pull it off는 어려운 일을 해낸다는 뜻입니다.","핵심 단어: fantastic news, congratulations, you pulled it off"]',
   'jun', 'I can''t believe it. My hands are still shaking. I almost froze when he asked about the cancellation clause.', '믿기지 않아요. 아직도 손이 떨려요. 해지 조항을 물었을 때는 얼어붙을 뻔했어요.'),
  ('pr_d12_signed', 2, 'jun',
   '"Almost" is the important word.', '중요한 말은 "뻔했다"입니다.',
   'For a second, my mind went blank.', 'Say that he did not freeze, and ask how he handled it.', '그래도 얼어붙지 않았다고 하고, 어떻게 풀었는지 물어보세요.',
   '[{"any":["handle it","handled it","what did you say"]}]',
   'But you didn''t freeze. How did you handle it?',
   '["But you didn''t call. How did you get home?","But you didn''t pay. How did you get a receipt?","But you didn''t ask."]',
   '["Let him tell the story. \\"How did you handle it?\\"","Key words: you didn''t freeze, how did you handle it"]', '["준이 직접 이야기하게 하세요. \\"How did you handle it?\\"","핵심 단어: you didn''t freeze, how did you handle it"]',
   'jun', 'I said seven days was too short for us and asked for thirty. He said, "That''s fair."', '7일은 우리에게 너무 짧다고 하고 30일을 요청했어요. 그랬더니 "타당하네요"라고 하더라고요.'),
  ('pr_d12_signed', 3, 'jun',
   'He is giving the credit away. You give it back.', '준이 공을 남에게 돌리고 있습니다. 당신은 그 공을 돌려줍니다.',
   'I just did what you told me.', 'Say no: he was the one in the room. Tell him to give himself some credit.', '아니라고 하세요. 그 자리에 있던 사람은 준이었다고요. 자기 공을 좀 인정하라고 말해 주세요.',
   '[{"any":["give yourself","credit","in the room"]}]',
   'No, you were the one in the room. Give yourself some credit.',
   '["No, you were the one in the photo. Give me back my phone.","No, you were first in line. Give the man your order.","No, you go ahead."]',
   '["Praise works best when it says what the person did.","Key words: you were the one in the room, give yourself some credit"]', '["칭찬은 그 사람이 무엇을 했는지 짚어 줄 때 가장 힘이 있습니다.","핵심 단어: you were the one in the room, give yourself some credit"]',
   'jun', 'Okay. Maybe a little. Oh, and Greg asked who to call day to day. I said you''re his main point of contact.', '네. 조금은요. 아, 그리고 그렉이 평소에 누구에게 연락하면 되는지 물어서, 프리야가 주 담당자라고 했어요.'),
  ('pr_d12_signed', 4, 'jun',
   'Signed is not finished. The real work starts now.', '서명했다고 끝난 것이 아닙니다. 진짜 일은 이제 시작입니다.',
   'I also told him about the kickoff next week and the status update every Friday. Was that okay?', 'Say that is exactly right, and that you will set up the kickoff with both teams for next week.', '정확히 잘했다고 하고, 다음 주에 양 팀이 함께하는 킥오프를 잡겠다고 하세요.',
   '[{"any":["set up","both teams","exactly right"]}]',
   'That''s exactly right. I''ll set up the kickoff with both teams for next week.',
   '["That''s exactly five dollars. I''ll put the change in the tip jar.","That''s exactly my size. I''ll take the blue one.","That''s exactly what I ordered."]',
   '["Confirm his promise, then say what you will do next.","Key words: exactly right, set up the kickoff, both teams, next week"]', '["준의 약속이 옳았다고 확인해 주고, 당신이 다음에 할 일을 말하세요.","핵심 단어: exactly right, set up the kickoff, both teams, next week"]',
   'jun', 'Great. My flight''s at three. Should I come into the office tonight?', '좋아요. 비행기는 세 시예요. 오늘 저녁에 사무실에 들를까요?'),
  ('pr_d12_signed', 5, 'jun',
   'He has been up since five two days in a row.', '준은 이틀 연속 새벽 다섯 시에 일어났습니다.',
   'I could write up the trip report.', 'Say absolutely not: he should go straight home and get some rest. You will celebrate on Monday.', '절대 안 된다고 하세요. 곧장 집에 가서 쉬라고요. 축하는 월요일에 하자고 하세요.',
   '[{"any":["get some rest","straight home","celebrate"]}]',
   'Absolutely not. Go straight home and get some rest. We''ll celebrate on Monday.',
   '["Absolutely not. Go straight to the checkout and get a refund.","Absolutely not. Go down the hall and turn left at the kitchen.","Absolutely not. It''s too spicy."]',
   '["A kind order: \\"Go straight home.\\" Then something to look forward to.","Key words: absolutely not, go straight home, get some rest, celebrate on Monday"]', '["다정한 명령입니다. \\"Go straight home.\\" 그리고 기대할 일을 하나 말해 주세요.","핵심 단어: absolutely not, go straight home, get some rest, celebrate on Monday"]',
   'jun', 'Deal. Have a great weekend, Priya!', '좋아요. 주말 잘 보내세요, 프리야!');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_d12_signed.its_official', 'pr_d12_signed', 'It''s official!', '이제 공식적으로 확정됐어요!', 'Said when something is finally signed, announced or decided.', '마침내 서명하거나 발표하거나 결정했을 때 하는 말입니다.', 'office'),
  ('pr_d12_signed.pulled_it_off', 'pr_d12_signed', 'You pulled it off.', '해냈네요.', '"Pull off" something hard = succeed at it. Stronger praise than "Good job."', '어려운 일을 pull off한다는 것은 해낸다는 뜻입니다. "Good job."보다 힘 있는 칭찬입니다.', 'office'),
  ('pr_d12_signed.almost_froze', 'pr_d12_signed', 'I almost froze.', '얼어붙을 뻔했어요.', '"Freeze" = be unable to speak or move because you are nervous. Also "My mind went blank."', 'freeze는 긴장해서 말도 몸도 굳는다는 뜻입니다. "My mind went blank."도 씁니다.', 'office'),
  ('pr_d12_signed.how_did_you_handle', 'pr_d12_signed', 'How did you handle it?', '어떻게 풀었어요?', 'Invites a person to tell their own success story.', '상대가 자기가 잘한 이야기를 직접 하게 하는 질문입니다.', 'office'),
  ('pr_d12_signed.give_yourself_credit', 'pr_d12_signed', 'Give yourself some credit.', '자기 공을 좀 인정하세요.', 'Said to someone who is too modest. Credit = praise for what you did.', '지나치게 겸손한 사람에게 하는 말입니다. credit은 해낸 일에 대한 인정입니다.', 'office'),
  ('pr_d12_signed.exactly_right', 'pr_d12_signed', 'That''s exactly right.', '정확히 잘했어요.', 'Confirms a decision someone made without you. It builds their confidence.', '상대가 혼자 내린 결정이 옳았다고 확인해 주는 말입니다. 자신감을 키워 줍니다.', 'office'),
  ('pr_d12_signed.set_up_the_kickoff', 'pr_d12_signed', 'I''ll set up the kickoff with both teams.', '양 팀이 함께하는 킥오프를 잡을게요.', '"Set up" a meeting = arrange it: the time, the room, the invite.', '회의를 set up한다는 것은 시간과 회의실, 초대장까지 준비한다는 뜻입니다.', 'meeting'),
  ('pr_d12_signed.get_some_rest', 'pr_d12_signed', 'Go straight home and get some rest.', '곧장 집에 가서 좀 쉬어요.', '"Straight home" = without stopping anywhere.', 'straight home은 어디에도 들르지 않고 바로 집으로 간다는 뜻입니다.', 'small-talk');

-- pr_d12_headcount: Sharing the credit, asking for headcount
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d12_headcount', 1, 'maya',
   'Maya''s office, Friday afternoon. The signed contract is on her screen.', '금요일 오후, 마야의 사무실입니다. 화면에 서명이 끝난 계약서가 떠 있습니다.',
   'Congratulations, Priya. You ran a great negotiation.', 'Thank her and share the credit: Jun closed it in the room, and Derek kept every date you promised.', '고맙다고 하고 공을 나누세요. 현장에서 계약을 마무리한 사람은 준이고, 약속한 날짜를 모두 지킨 사람은 데릭입니다.',
   '[{"any":["credit","jun closed","derek kept"]}]',
   'Thank you. Credit where it''s due: Jun closed it in the room, and Derek kept every date we promised.',
   '["Thank you. Cash or card: I''ll pay for the coffee, and you get the muffins.","Thank you. Paper or plastic: I''ll carry the eggs.","Thank you. Same to you."]',
   '["Accept the praise, then name who did what.","Key words: credit where it''s due, Jun closed it, Derek kept every date"]', '["칭찬을 받아들인 뒤, 누가 무엇을 했는지 이름을 들어 말하세요.","핵심 단어: credit where it''s due, Jun closed it, Derek kept every date"]',
   'maya', 'Noted. I''ll mention both of them to the leadership team.', '기억해 둘게요. 경영진에게 두 사람 이야기를 꼭 할게요.'),
  ('pr_d12_headcount', 2, 'maya',
   'Maya opens the project plan. She always looks ahead.', '마야가 프로젝트 계획을 엽니다. 마야는 언제나 앞일을 봅니다.',
   'So. Phase one by November first. Are we staffed for it?', 'Be honest: not quite. With two developers, the team is stretched thin.', '솔직하게 말하세요. 충분하지는 않다고요. 개발자 두 명으로는 팀이 빠듯합니다.',
   '[{"any":["stretched thin","not quite","stretched"]}]',
   'Honestly, not quite. With two developers, we''re stretched thin.',
   '["Honestly, not hungry. With two muffins, I''m full until dinner.","Honestly, no idea. With two buses, it takes about an hour.","Honestly, no thanks."]',
   '["\\"Not quite\\" is a soft no. \\"Stretched thin\\" = too much work for too few people.","Key words: honestly, not quite, stretched thin"]', '["\\"Not quite\\"는 부드러운 부정입니다. stretched thin은 사람에 비해 일이 너무 많다는 뜻입니다.","핵심 단어: honestly, not quite, stretched thin"]',
   'maya', 'I was afraid of that. What are you asking for?', '그럴까 봐 걱정했어요. 뭘 요청하려는 거예요?'),
  ('pr_d12_headcount', 3, 'maya',
   'Bottom line first. You have practiced this sentence.', '결론부터입니다. 이 문장은 미리 연습해 두었습니다.',
   'Go ahead. I''m listening.', 'Say you would like to make the case for one more developer on the team.', '팀에 개발자가 한 명 더 필요한 이유를 설명하고 싶다고 하세요.',
   '[{"any":["make the case","one more developer","another developer","headcount"]}]',
   'I''d like to make the case for one more developer on the team.',
   '["I''d like to make a reservation for one more person at the table.","I''d like to make the bed before we leave the room.","I''d like to make a left turn here."]',
   '["\\"Make the case for\\" = explain why something is needed.","Key words: make the case for, one more developer"]', '["make the case for는 그것이 왜 필요한지 근거를 대며 설명한다는 뜻입니다.","핵심 단어: make the case for, one more developer"]',
   'maya', 'Headcount is tight this year. Why can''t we do it with the people we have?', '올해는 인원 예산이 빠듯해요. 지금 있는 사람들로는 왜 안 되죠?');

REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d12_headcount', 4, 'maya',
   'You have the numbers ready: two developers, eight weeks, no room for anything to go wrong.', '숫자는 준비되어 있습니다. 개발자 두 명에 8주, 그리고 무엇 하나 어긋날 여유가 없습니다.',
   'Convince me.', 'Explain the risk: with two developers there is no slack. If one of them is out for a week, November first slips.', '위험을 설명하세요. 개발자 두 명으로는 여유가 없습니다. 한 명이 한 주만 빠져도 11월 1일이 밀립니다.',
   '[{"any":["no slack","out for a week","any slack"]}]',
   'With two developers, we have no slack. If one of them is out for a week, November first slips.',
   '["With two eggs, we have no breakfast. If one of them breaks, we eat toast.","With two umbrellas, we have no problem. If one of them breaks, we share.","With two sugars, please."]',
   '["\\"Slack\\" = extra time or people for when things go wrong.","Key words: no slack, out for a week, November first slips"]', '["slack은 일이 틀어질 때를 대비한 여분의 시간이나 사람입니다.","핵심 단어: no slack, out for a week, November first slips"]',
   'maya', 'That''s a real risk. What about a contractor? That would be faster.', '그건 실제로 있을 수 있는 위험이네요. 계약직은 어때요? 그쪽이 더 빠를 텐데요.'),
  ('pr_d12_headcount', 5, 'maya',
   'A contractor could start in two weeks. But the work will not end in November.', '계약직은 2주 뒤면 시작할 수 있습니다. 하지만 일은 11월에 끝나지 않습니다.',
   'Would that solve it?', 'Say you are open to a contractor to bridge the gap, but with phase two and the support contract, this is long-term work.', '공백을 메우는 용도라면 계약직도 좋다고 하되, 2단계와 지원 계약이 있으니 이건 장기적인 일이라고 하세요.',
   '[{"any":["bridge the gap","open to","long term"]}]',
   'I''m open to a contractor to bridge the gap. But with phase two and the support contract, this is long-term work.',
   '["I''m open until nine on weekdays. But on Sundays, we close at six.","I''m up for pizza tonight. But with the rain, nobody wants to go out.","I''m open on Monday."]',
   '["Accept part of her idea, then say why it is not enough.","Key words: open to, a contractor, bridge the gap, long-term work"]', '["마야의 생각을 일부 받아들인 뒤, 그것만으로는 부족한 이유를 말하세요.","핵심 단어: open to, a contractor, bridge the gap, long-term work"]',
   'maya', 'Fair. A contractor now, and one full-time position. I''ll approve it. Talk to Linda about opening the job.', '맞아요. 지금은 계약직, 그리고 정규직 한 자리. 승인할게요. 채용 공고는 린다와 이야기해요.'),
  ('pr_d12_headcount', 6, 'maya',
   'One position, approved. You try not to smile too much.', '한 자리가 승인됐습니다. 너무 활짝 웃지 않으려고 애씁니다.',
   'Is there anything else?', 'Say that is all, thank her, and say you will get the job description to Linda this afternoon.', '그게 전부라고 하고 고맙다고 하세요. 오늘 오후에 린다에게 직무 기술서를 전달하겠다고 하세요.',
   '[{"any":["job description","linda"]}]',
   'That''s all. Thank you, Maya. I''ll get the job description to Linda this afternoon.',
   '["That''s all. Thank you, Rosa. I''ll get the check at the counter.","That''s all. Thank you, Mike. I''ll get the bags myself.","That''s all for today."]',
   '["Close, thank her, and say your next step.","Key words: that''s all, the job description, to Linda, this afternoon"]', '["마무리하고, 고맙다고 하고, 다음에 할 일을 말하세요.","핵심 단어: that''s all, the job description, to Linda, this afternoon"]',
   'maya', 'Good. And Priya? Take the weekend off. Let me know if you have any questions.', '좋아요. 그리고 프리야, 주말에는 푹 쉬어요. 궁금한 게 있으면 말해 줘요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_d12_headcount.credit_where_due', 'pr_d12_headcount', 'Credit where it''s due.', '공은 마땅히 받을 사람에게 돌려야죠.', 'Short for "Give credit where credit is due." Then name the people.', '"Give credit where credit is due."를 줄인 말입니다. 이어서 사람들의 이름을 말하세요.', 'office'),
  ('pr_d12_headcount.are_we_staffed', 'pr_d12_headcount', 'Are we staffed for it?', '그 일을 할 인원이 되나요?', '"Staffed" = having enough people. "Understaffed" = too few.', 'staffed는 사람이 충분히 있다는 뜻이고, understaffed는 모자란다는 뜻입니다.', 'office'),
  ('pr_d12_headcount.stretched_thin', 'pr_d12_headcount', 'We''re stretched thin.', '우리는 일손이 빠듯해요.', 'Too few people doing too much work. It describes the team, not a complaint about anyone.', '적은 사람이 너무 많은 일을 한다는 뜻입니다. 누구를 탓하는 말이 아니라 팀의 상태를 말합니다.', 'office'),
  ('pr_d12_headcount.make_the_case', 'pr_d12_headcount', 'I''d like to make the case for one more developer.', '개발자가 한 명 더 필요한 이유를 말씀드리고 싶어요.', 'Tells your manager that a request is coming, with reasons.', '근거를 갖춘 요청을 하겠다고 매니저에게 알리는 말입니다.', 'meeting'),
  ('pr_d12_headcount.headcount', 'pr_d12_headcount', 'Headcount is tight this year.', '올해는 인원 예산이 빠듯해요.', 'Headcount = the number of people a team is allowed to employ.', 'headcount는 팀이 고용할 수 있도록 허락된 인원수입니다.', 'office'),
  ('pr_d12_headcount.no_slack', 'pr_d12_headcount', 'We have no slack.', '우리에게는 여유가 없어요.', 'Slack = spare time or capacity. A plan with no slack breaks at the first problem.', 'slack은 남는 시간이나 여력입니다. 여유가 없는 계획은 첫 문제에서 무너집니다.', 'office'),
  ('pr_d12_headcount.bridge_the_gap', 'pr_d12_headcount', 'a contractor to bridge the gap', '공백을 메울 계약직', '"Bridge the gap" = cover the time until the lasting solution arrives.', 'bridge the gap은 제대로 된 해결책이 올 때까지의 시간을 메운다는 뜻입니다.', 'office'),
  ('pr_d12_headcount.open_to', 'pr_d12_headcount', 'I''m open to a contractor.', '계약직도 괜찮다고 생각해요.', '"I''m open to …" = I am willing to consider it.', '"I''m open to …"는 고려할 뜻이 있다는 말입니다.', 'meeting');

-- pr_d12_hiring: Opening a position with Linda
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d12_hiring', 1, 'linda',
   'The HR office. Linda has a blank form open and a pen in her hand.', '인사팀 사무실입니다. 린다가 빈 양식을 띄워 놓고 펜을 들고 있습니다.',
   'Hi, Priya! Maya told me you''d stop by. A new position, how exciting! Is it a new role or a backfill?', 'Say it is a new role: a full-time developer for the Summit Retail project.', '새로 생기는 자리라고 하세요. 서밋 리테일 프로젝트를 맡을 정규직 개발자입니다.',
   '[{"any":["new role","full time developer"]}]',
   'It''s a new role: a full-time developer for the Summit Retail project.',
   '["It''s a new recipe: a full pound of peaches for one pie.","It''s a new route: a direct bus from Cedar Street to the airport.","It''s a new umbrella."]',
   '["A \\"backfill\\" replaces someone who left. This job did not exist before.","Key words: a new role, a full-time developer"]', '["backfill은 나간 사람의 자리를 채우는 것입니다. 이번 자리는 전에 없던 자리입니다.","핵심 단어: a new role, a full-time developer"]',
   'linda', 'Wonderful. Then we need a job requisition. We call it a req.', '잘됐네요. 그러면 채용 요청서가 필요해요. 줄여서 req라고 불러요.'),
  ('pr_d12_hiring', 2, 'linda',
   'Linda moves to the second line of the form.', '린다가 양식의 둘째 줄로 넘어갑니다.',
   'Who''s the hiring manager? That''s the person the new hire reports to.', 'Say Maya is the hiring manager, and you will be on the interview panel, along with Derek.', '채용 책임자는 마야이고, 당신은 데릭과 함께 면접관으로 참여한다고 하세요.',
   '[{"any":["hiring manager","interview panel"]}]',
   'Maya is the hiring manager. I''ll be on the interview panel, along with Derek.',
   '["Maya is the early bird. I''ll be on the nine o''clock bus, along with Derek.","Maya is on vacation. I''ll be at the diner, along with Carl.","Maya is in a meeting."]',
   '["Answer her question, then say what your own part is.","Key words: the hiring manager, on the interview panel, along with Derek"]', '["질문에 답한 뒤, 당신이 맡을 역할을 말하세요.","핵심 단어: the hiring manager, on the interview panel, along with Derek"]',
   'linda', 'Maya, you and Derek. Got it.', '마야, 프리야, 데릭. 알겠어요.'),
  ('pr_d12_hiring', 3, 'linda',
   'You have a number in your head, but it is only a guess.', '머릿속에 숫자가 하나 있지만, 짐작일 뿐입니다.',
   'Do you have a salary range in mind? We have to list it in the posting.', 'Say you would rather not guess, and ask what the approved range is for a mid-level developer.', '짐작으로 말하고 싶지 않다고 하고, 중간급 개발자에게 승인된 범위가 얼마인지 물어보세요.',
   '[{"any":["approved range","pay band","rather not guess"]}]',
   'I''d rather not guess. What''s the approved range for a mid-level developer?',
   '["I''d rather not drive. What''s the fastest bus for a trip downtown?","I''d rather not cook. What''s the special for a rainy Sunday?","I''d rather not say."]',
   '["\\"I''d rather not …\\" is a polite way to decline. Then ask the expert.","Key words: I''d rather not guess, the approved range, mid-level developer"]', '["\\"I''d rather not …\\"은 정중히 사양하는 말입니다. 그리고 전문가에게 물어보세요.","핵심 단어: I''d rather not guess, the approved range, mid-level developer"]',
   'linda', 'For that level, it''s ninety-five to one hundred fifteen thousand a year, plus benefits.', '그 직급이면 연 9만 5천에서 11만 5천 달러이고, 복리후생은 별도예요.'),
  ('pr_d12_hiring', 4, 'linda',
   'Phase one is due on November first.', '1단계의 기한은 11월 1일입니다.',
   'And how soon do you need someone?', 'Say ideally within six weeks, and ask how long the process usually takes.', '가능하면 6주 안이면 좋겠다고 하고, 채용 절차가 보통 얼마나 걸리는지 물어보세요.',
   '[{"any":["ideally","how long","six weeks"]}]',
   'Ideally within six weeks. How long does the process usually take?',
   '["Usually within six blocks. How far does the 12 bus go?","Usually with oat milk. How hot does the latte come?","Usually on Saturdays."]',
   '["\\"Ideally\\" gives your wish without making it a demand.","Key words: ideally, within six weeks, how long, the process"]', '["ideally는 요구가 아니라 바람으로 말하게 해 줍니다.","핵심 단어: ideally, within six weeks, how long, the process"]',
   'linda', 'From posting to offer, about five weeks if we move quickly. Referrals are faster, and there''s a referral bonus.', '공고부터 입사 제안까지, 서두르면 5주쯤 걸려요. 추천은 더 빠르고, 추천 보너스도 있어요.'),
  ('pr_d12_hiring', 5, 'linda',
   'Your draft of the job description is almost done.', '직무 기술서 초안은 거의 다 써 두었습니다.',
   'I''ll need the job description before I can post it. When can you get it to me?', 'Say she will have a draft by four o''clock, and that she should feel free to mark it up.', '네 시까지 초안을 보내겠다고 하고, 마음껏 고쳐 달라고 하세요.',
   '[{"any":["draft","mark it up"]}]',
   'You''ll have a draft by four o''clock. Feel free to mark it up.',
   '["You''ll have a table by four o''clock. Feel free to wait at the counter.","You''ll have sun by four o''clock. Feel free to leave your umbrella.","You''ll have fun."]',
   '["Give the time, then invite her changes.","Key words: a draft by four o''clock, feel free to, mark it up"]', '["시간을 말하고, 고쳐도 좋다고 말하세요.","핵심 단어: a draft by four o''clock, feel free to, mark it up"]',
   'linda', 'I will. We''ll have it posted by Monday morning. And congratulations on the contract!', '그럴게요. 월요일 아침까지 공고를 올릴게요. 그리고 계약 축하해요!');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_d12_hiring.backfill', 'pr_d12_hiring', 'Is it a new role or a backfill?', '새로 생기는 자리예요, 아니면 빈자리를 채우는 거예요?', 'A backfill replaces a person who left. A new role adds to the headcount.', 'backfill은 나간 사람의 자리를 채우는 것이고, 새 자리는 인원이 늘어나는 것입니다.', 'office'),
  ('pr_d12_hiring.job_req', 'pr_d12_hiring', 'a job requisition (a req)', '채용 요청서', 'The internal form that approves a hire. "The req is open" = you may start hiring.', '채용을 승인하는 내부 문서입니다. "The req is open"은 채용을 시작해도 된다는 뜻입니다.', 'office'),
  ('pr_d12_hiring.hiring_manager', 'pr_d12_hiring', 'Who''s the hiring manager?', '채용 책임자가 누구예요?', 'The manager who makes the final decision and will lead the new person.', '최종 결정을 내리고 새로 온 사람을 이끌 매니저입니다.', 'office'),
  ('pr_d12_hiring.reports_to', 'pr_d12_hiring', 'the person the new hire reports to', '새 직원이 보고하는 사람', '"Report to" someone = have them as your manager.', '누구에게 report to한다는 것은 그 사람이 내 매니저라는 뜻입니다.', 'office'),
  ('pr_d12_hiring.interview_panel', 'pr_d12_hiring', 'I''ll be on the interview panel.', '저는 면접관으로 참여할게요.', 'The group of people who interview a candidate.', '지원자를 면접하는 사람들의 모임입니다.', 'office'),
  ('pr_d12_hiring.salary_range', 'pr_d12_hiring', 'Do you have a salary range in mind?', '생각하는 연봉 범위가 있어요?', 'Job postings often list the lowest and highest pay for the role.', '채용 공고에는 그 자리의 최저와 최고 급여를 밝히는 경우가 많습니다.', 'office'),
  ('pr_d12_hiring.referral_bonus', 'pr_d12_hiring', 'There''s a referral bonus.', '추천 보너스가 있어요.', 'Money an employee gets when someone they recommended is hired.', '추천한 사람이 채용되면 직원이 받는 돈입니다.', 'office'),
  ('pr_d12_hiring.mark_it_up', 'pr_d12_hiring', 'Feel free to mark it up.', '마음껏 고쳐 주세요.', '"Mark up" a document = write changes and comments on it.', '문서를 mark up한다는 것은 고칠 점과 의견을 적어 넣는다는 뜻입니다.', 'office');

-- pr_w2_carl: Good news on a park bench
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_w2_carl', 1, 'carl',
   'Saturday morning, sunny and warm. Carl is on his bench with a bag of charcoal at his feet.', '화창하고 따뜻한 토요일 아침입니다. 칼이 발치에 숯 한 봉지를 두고 늘 앉는 벤치에 앉아 있습니다.',
   'There she is! You look like somebody who had a good week.', 'Say you did: you closed a big deal yesterday.', '그랬다고 하세요. 어제 큰 계약을 성사시켰다고요.',
   '[{"any":["big deal","closed a","closed the","signed"]}]',
   'I did! We closed a big deal yesterday.',
   '["I did! We climbed a big hill yesterday.","I did! We cooked a big dinner for my sister.","I did! We painted the kitchen."]',
   '["To \\"close a deal\\" is to finish it with a signed agreement.","Key words: we closed a big deal, yesterday"]', '["close a deal은 서명까지 마쳐 거래를 성사시킨다는 뜻입니다.","핵심 단어: we closed a big deal, yesterday"]',
   'carl', 'Well, how about that! Congratulations. So what did you have to give up to get it?', '이야, 그것참 잘됐네! 축하해. 그래, 그걸 따내려고 뭘 내줬나?'),
  ('pr_w2_carl', 2, 'carl',
   'Carl bought bus parts for thirty years. He knows there is no deal without a price.', '칼은 30년 동안 버스 부품을 사들였습니다. 대가 없는 거래가 없다는 것을 잘 압니다.',
   'Nobody signs for free.', 'Say a small discount, but you got a one-year contract in return. Call it a win-win.', '할인을 조금 해 줬지만 그 대신 1년 계약을 받았다고 하세요. 양쪽 모두에게 좋은 거래라고요.',
   '[{"any":["in return","win win"]}]',
   'A small discount, but we got a one-year contract in return. I''d call that a win-win.',
   '["A small coffee, but I got a free muffin with it. I''d call that breakfast.","A small apartment, but I got a view of the water. I''d call that home.","A small one, please."]',
   '["What you gave, what you got \\"in return\\", and a name for the result.","Key words: a small discount, in return, a win-win"]', '["무엇을 주었는지, 그 대신(in return) 무엇을 받았는지, 그리고 그 결과를 한마디로 말하세요.","핵심 단어: a small discount, in return, a win-win"]',
   'carl', 'Win-win. That''s how I bought parts for thirty years. So, what are you doing with your Saturday? Don''t tell me you''re working.', '양쪽 다 좋은 거래라. 나도 30년 동안 그렇게 부품을 샀지. 그래, 토요일엔 뭘 하나? 설마 일한다는 건 아니겠지.'),
  ('pr_w2_carl', 3, 'carl',
   'Your laptop is at home, closed. Maya told you to take the weekend off.', '노트북은 집에 덮어 두고 왔습니다. 마야도 주말에는 쉬라고 했습니다.',
   'You work too hard. I''ve said it before.', 'Say no way: you are unplugging this weekend. No email until Monday.', '절대 아니라고 하세요. 이번 주말에는 일에서 완전히 손을 뗀다고요. 월요일까지 이메일은 안 봅니다.',
   '[{"any":["unplugging","unplug","no email"]}]',
   'No way. I''m unplugging this weekend. No email until Monday.',
   '["No way. I''m moving this weekend. No furniture until Tuesday.","No way. I''m driving this time. No bus until the airport.","No way. I''m full."]',
   '["\\"Unplug\\" = stop working and stay away from screens.","Key words: I''m unplugging, no email until Monday"]', '["unplug는 일을 멈추고 화면에서 떨어져 지낸다는 뜻입니다.","핵심 단어: I''m unplugging, no email until Monday"]',
   'carl', 'I''ll believe it when I see it.', '눈으로 봐야 믿겠는걸.'),
  ('pr_w2_carl', 4, 'carl',
   'He taps the bag of charcoal with his shoe.', '칼이 구두로 숯 봉지를 툭 칩니다.',
   'I''m having a barbecue for my tenants at four. Jun''s coming, the new kid from your office. Why don''t you swing by?', 'Say you would love to, and ask what you can bring.', '기꺼이 가겠다고 하고, 무엇을 가져가면 좋을지 물어보세요.',
   '[{"any":["can i bring","should i bring","love to"]}]',
   'I''d love to. What can I bring?',
   '["I''d love a refill. What kind of pie is that?","I''d like a receipt. What time do you close?","I''d rather walk."]',
   '["At an American cookout a guest always asks \\"What can I bring?\\"","Key words: I''d love to, what can I bring"]', '["미국에서 바비큐에 초대받은 손님은 으레 \\"What can I bring?\\" 하고 묻습니다.","핵심 단어: I''d love to, what can I bring"]',
   'carl', 'Just yourself. Well, maybe some of that lemonade from the market.', '몸만 오면 돼. 뭐, 마켓에서 파는 그 레모네이드나 좀 가져오든가.'),
  ('pr_w2_carl', 5, 'carl',
   'Carl stands up and lifts the charcoal onto his shoulder.', '칼이 일어나 숯 봉지를 어깨에 멥니다.',
   'Four o''clock, the yard behind Maple Street Apartments. Don''t be late. The ribs go fast.', 'Say you would not miss it, and you will be there at four, lemonade in hand.', '꼭 가겠다고 하고, 네 시에 레모네이드를 들고 가겠다고 하세요.',
   '[{"any":["would not miss","be there","see you at four"]}]',
   'I wouldn''t miss it. I''ll be there at four, lemonade in hand.',
   '["I wouldn''t eat that. It''s been in the fridge since Monday.","I wouldn''t park there. It''s a tow zone until six.","I wouldn''t know."]',
   '["\\"I wouldn''t miss it\\" is a warm, strong yes.","Key words: I wouldn''t miss it, I''ll be there at four"]', '["\\"I wouldn''t miss it\\"은 따뜻하면서도 힘 있는 승낙입니다.","핵심 단어: I wouldn''t miss it, I''ll be there at four"]',
   'carl', 'See you at four, Priya. Bring an appetite.', '네 시에 보세, 프리야. 배는 비워서 오고.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_w2_carl.closed_a_deal', 'pr_w2_carl', 'We closed a big deal.', '큰 계약을 성사시켰어요.', '"Close a deal" = complete it. A person who is good at this is "a closer".', 'close a deal은 거래를 마무리한다는 뜻입니다. 이것을 잘하는 사람을 a closer라고 합니다.', 'small-talk'),
  ('pr_w2_carl.how_about_that', 'pr_w2_carl', 'Well, how about that!', '이야, 그것참 잘됐네!', 'Shows happy surprise at good news. It is not a question.', '좋은 소식에 기쁘게 놀라는 말입니다. 질문이 아닙니다.', 'small-talk'),
  ('pr_w2_carl.in_return', 'pr_w2_carl', 'We got a one-year contract in return.', '그 대신 1년 계약을 받았어요.', '"In return" = as the thing you get back for what you gave.', 'in return은 내준 것에 대한 대가로 받는다는 뜻입니다.', 'small-talk'),
  ('pr_w2_carl.win_win', 'pr_w2_carl', 'I''d call that a win-win.', '양쪽 모두에게 좋은 거래죠.', 'A result that is good for both sides.', '양쪽 모두에게 좋은 결과를 말합니다.', 'small-talk'),
  ('pr_w2_carl.unplugging', 'pr_w2_carl', 'I''m unplugging this weekend.', '이번 주말에는 일에서 손을 뗄 거예요.', 'Like pulling a plug out of the wall: no work, no email.', '벽에서 플러그를 뽑듯이 일도 이메일도 끊는다는 뜻입니다.', 'small-talk'),
  ('pr_w2_carl.believe_it_when', 'pr_w2_carl', 'I''ll believe it when I see it.', '눈으로 봐야 믿겠는걸.', 'Friendly doubt about a promise.', '약속을 살짝 의심하며 놀리는 말입니다.', 'small-talk'),
  ('pr_w2_carl.what_can_i_bring', 'pr_w2_carl', 'What can I bring?', '뭘 가져갈까요?', 'The polite answer to an invitation. If the host says "Just yourself", bring a drink or dessert anyway.', '초대에 답하는 예의 바른 말입니다. 주인이 "Just yourself"라고 해도 음료나 디저트를 가져가세요.', 'small-talk'),
  ('pr_w2_carl.wouldnt_miss_it', 'pr_w2_carl', 'I wouldn''t miss it.', '꼭 갈게요.', 'Stronger and warmer than "I''ll come."', '"I''ll come."보다 힘 있고 따뜻한 말입니다.', 'small-talk');

-- pr_w2_rainy: A rainy Sunday at the diner
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_w2_rainy', 1, 'rosa',
   'Sunday. The shower starts when you are one block from the diner. You run the rest of the way.', '일요일입니다. 다이너까지 한 블록 남았을 때 소나기가 쏟아집니다. 남은 길을 뛰어갑니다.',
   'Hi, hon! Look at you, you''re soaked. Did you get caught in the rain?', 'Say you got caught in a downpour without your umbrella, and ask if it is okay to sit at the counter.', '우산 없이 폭우를 만났다고 하고, 카운터에 앉아도 되는지 물어보세요.',
   '[{"any":["downpour","caught in","at the counter"]}]',
   'I got caught in a downpour without my umbrella. Is it okay if I sit at the counter?',
   '["I got lost in the parking lot without my phone. Is it okay if I borrow yours?","I got stuck in a meeting without any coffee. Is it okay if I leave early?","I got a haircut."]',
   '["\\"Get caught in\\" the rain = be outside when it starts. Very heavy rain is a \\"downpour\\".","Key words: got caught in a downpour, sit at the counter"]', '["비에 get caught in했다는 것은 밖에 있다가 비를 만났다는 뜻입니다. 아주 세찬 비는 downpour입니다.","핵심 단어: got caught in a downpour, sit at the counter"]',
   'rosa', 'Sit anywhere, hon. Let me get you some coffee to warm you up.', '아무 데나 앉아요. 몸 좀 녹이게 커피부터 줄게요.'),
  ('pr_w2_rainy', 2, 'rosa',
   'The coffee is hot and the windows are steamed up.', '커피는 뜨겁고 창문에는 김이 서려 있습니다.',
   'Now, what can I get you?', 'Ask what she recommends on a day like this.', '이런 날에는 무엇을 추천하는지 물어보세요.',
   '[{"any":["recommend","day like this","what is good"]}]',
   'What do you recommend on a day like this?',
   '["What do you charge for a room like this?","What do you think of my new umbrella?","What do you do on weekends?"]',
   '["Let the expert choose: \\"What do you recommend …?\\"","Key words: what do you recommend, on a day like this"]', '["전문가에게 맡기세요. \\"What do you recommend …?\\"","핵심 단어: what do you recommend, on a day like this"]',
   'rosa', 'Chicken noodle soup and a grilled cheese. It''s what I''d have. Cup or bowl?', '치킨 누들 수프에 그릴드 치즈죠. 나라면 그걸 먹겠어요. 컵으로 줄까요, 볼로 줄까요?'),
  ('pr_w2_rainy', 3, 'rosa',
   'A cup is small. A bowl is a meal.', '컵은 작습니다. 볼은 한 끼가 됩니다.',
   'Cup or bowl, hon?', 'Say a bowl, with the grilled cheese, and that you could use some comfort food.', '볼로 달라고 하고 그릴드 치즈도 주문하세요. 마음이 편안해지는 음식이 먹고 싶다고 하세요.',
   '[{"any":["bowl","comfort food"]}]',
   'A bowl, please, with the grilled cheese. I could use some comfort food.',
   '["A window seat, please, with extra legroom. I could use some sleep.","A large, please, with oat milk. I could use some caffeine.","A receipt, please."]',
   '["\\"I could use …\\" = I would really like or need it.","Key words: a bowl, the grilled cheese, I could use, comfort food"]', '["\\"I could use …\\"는 그것이 정말 필요하거나 반갑겠다는 뜻입니다.","핵심 단어: a bowl, the grilled cheese, I could use, comfort food"]',
   'rosa', 'One bowl, one grilled cheese. Coming right up.', '수프 한 볼, 그릴드 치즈 하나. 금방 나와요.'),
  ('pr_w2_rainy', 4, 'rosa',
   'The bowl is empty. Outside it is still coming down.', '그릇이 비었습니다. 밖에는 아직도 비가 쏟아집니다.',
   'More coffee, hon? Refills are free.', 'Say yes, please: you are in no hurry, and you will wait out the rain.', '네, 달라고 하세요. 서두를 일이 없으니 비가 그칠 때까지 기다리겠다고요.',
   '[{"any":["wait out","no hurry","no rush"]}]',
   'Yes, please. I''m in no hurry. I''ll wait out the rain.',
   '["Yes, please. I''m in the blue car. I''ll wait by the door.","Yes, please. I''m in row twelve. I''ll take the aisle.","Yes, please. Paper is fine."]',
   '["\\"Wait out\\" the rain = stay inside until it stops.","Key words: I''m in no hurry, wait out the rain"]', '["비를 wait out한다는 것은 그칠 때까지 안에서 기다린다는 뜻입니다.","핵심 단어: I''m in no hurry, wait out the rain"]',
   'rosa', 'Stay as long as you like. Pie of the day is apple. Can I tempt you with a slice?', '있고 싶은 만큼 있어요. 오늘의 파이는 사과예요. 한 조각 어때요?'),
  ('pr_w2_rainy', 5, 'rosa',
   'The pie looks wonderful. But the bowl was big.', '파이가 정말 맛있어 보입니다. 하지만 수프가 한가득이었습니다.',
   'It came out of the oven an hour ago.', 'Say you are stuffed, but ask if you could get a slice to go.', '배가 꽉 찼다고 하되, 한 조각 포장해 갈 수 있는지 물어보세요.',
   '[{"any":["to go","stuffed"]}]',
   'I''m stuffed, but could I get a slice to go?',
   '["I''m lost, but could I get a map of downtown?","I''m late, but could I get a seat in the back?","I''m early, I know."]',
   '["\\"Stuffed\\" = very full. Food you take with you is \\"to go\\".","Key words: I''m stuffed, a slice to go"]', '["stuffed는 배가 아주 부르다는 뜻입니다. 가지고 가는 음식은 to go라고 합니다.","핵심 단어: I''m stuffed, a slice to go"]',
   'rosa', 'One slice of apple, boxed up. Here''s your check, hon: sixteen dollars, so seventeen thirty-two with tax.', '사과 파이 한 조각, 포장해 줄게요. 계산서 여기 있어요. 16달러니까, 세금 포함해서 17달러 32센트예요.'),
  ('pr_w2_rainy', 6, 'rosa',
   'You put a twenty on the counter. That leaves $2.68 for Rosa, about seventeen percent of sixteen dollars.', '카운터에 20달러 지폐를 올려놓습니다. 로사에게 2달러 68센트가 남으니, 16달러의 17퍼센트쯤 됩니다.',
   'Let me get your change.', 'Tell her that is okay, and to keep the change.', '괜찮다고 하고, 거스름돈은 가지라고 하세요.',
   '[{"any":["keep the change","keep it"]}]',
   'That''s okay. Keep the change.',
   '["That''s okay. Keep the door open.","That''s okay. Keep walking until the fountain.","That''s okay. I''ll wait."]',
   '["With cash, the change can be the tip. Check that it is 15 to 20 percent.","Key words: that''s okay, keep the change"]', '["현금으로 낼 때는 거스름돈을 팁으로 남길 수 있습니다. 15~20퍼센트가 되는지 확인하세요.","핵심 단어: that''s okay, keep the change"]',
   'rosa', 'Thank you, hon! Look, the sun''s coming out. Stay dry out there.', '고마워요! 저기 봐요, 해가 나네요. 비 맞지 말고 가요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_w2_rainy.soaked', 'pr_w2_rainy', 'You''re soaked.', '흠뻑 젖었네요.', 'Completely wet. Also "soaking wet" and "drenched".', '완전히 젖었다는 뜻입니다. soaking wet, drenched도 씁니다.', 'small-talk'),
  ('pr_w2_rainy.caught_in_a_downpour', 'pr_w2_rainy', 'I got caught in a downpour.', '폭우를 만났어요.', 'A downpour is sudden, heavy rain. "Showers" are light and come and go.', 'downpour는 갑자기 세차게 쏟아지는 비이고, showers는 가볍게 오다 말다 하는 비입니다.', 'small-talk'),
  ('pr_w2_rainy.day_like_this', 'pr_w2_rainy', 'What do you recommend on a day like this?', '이런 날에는 뭘 추천하세요?', 'Servers know the menu. Asking them is normal and friendly.', '종업원은 메뉴를 잘 압니다. 물어보는 것은 자연스럽고 친근한 일입니다.', 'food'),
  ('pr_w2_rainy.cup_or_bowl', 'pr_w2_rainy', 'Cup or bowl?', '컵으로 드릴까요, 볼로 드릴까요?', 'Soup sizes. A cup is a small side, a bowl is a full serving.', '수프의 크기입니다. cup은 곁들이는 작은 양이고 bowl은 한 그릇입니다.', 'food'),
  ('pr_w2_rainy.comfort_food', 'pr_w2_rainy', 'I could use some comfort food.', '마음이 편안해지는 음식이 먹고 싶어요.', 'Simple, warm food that makes you feel better: soup, grilled cheese, mac and cheese.', '먹으면 기분이 나아지는 소박하고 따뜻한 음식입니다. 수프, 그릴드 치즈, 맥 앤드 치즈 같은 것들입니다.', 'food'),
  ('pr_w2_rainy.wait_out_the_rain', 'pr_w2_rainy', 'I''ll wait out the rain.', '비가 그칠 때까지 기다릴게요.', '"Wait out" something = stay until it is over.', 'wait out은 그것이 끝날 때까지 기다린다는 뜻입니다.', 'small-talk'),
  ('pr_w2_rainy.slice_to_go', 'pr_w2_rainy', 'I''m stuffed, but could I get a slice to go?', '배가 꽉 찼는데, 한 조각 포장해 주시겠어요?', '"To go" = to take with you. The opposite is "for here".', 'to go는 가지고 간다는 뜻이고, 반대말은 for here입니다.', 'food'),
  ('pr_w2_rainy.keep_the_change', 'pr_w2_rainy', 'Keep the change.', '거스름돈은 가지세요.', 'Leaves the change as the tip when you pay in cash.', '현금으로 낼 때 거스름돈을 팁으로 남기는 말입니다.', 'food');

